package io.github.giwasawa.bosslab;

import com.google.gson.Gson;
import com.google.inject.Provides;
import io.github.giwasawa.bosslab.bosses.doom.DoomModule;
import io.github.giwasawa.bosslab.core.BossLabConfig;
import io.github.giwasawa.bosslab.core.BossLabPanel;
import io.github.giwasawa.bosslab.core.BossModule;
import io.github.giwasawa.bosslab.core.BossSpec;
import io.github.giwasawa.bosslab.core.InventoryTracker;
import io.github.giwasawa.bosslab.core.JsonlWriter;
import io.github.giwasawa.bosslab.core.RunRecorder;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;

/**
 * Boss Lab: records boss runs to local files for later analysis.
 *
 * <p>Data only. The plugin never helps during a fight. There is no overlay, no timer, no
 * counter, no cue, no prayer hint, no attack prediction and no highlighting. It adds no
 * menu entries, changes no menus, generates no input, automates nothing, and records
 * nothing about other players.
 *
 * <p>It makes no network requests of its own. Prices come from RuneLite's
 * {@code ItemManager}, a local lookup in the table RuneLite maintains by itself, so this
 * plugin adds zero requests to the wiki or anyone else however many players install it.
 *
 * <p>No personal data is ever written: no character name, account hash or id, email, IP,
 * chat from other players, other players' names, or any location outside the boss area.
 * Log files are named generically.
 *
 * <p>Event handlers copy small values only. File writes and gzip rotation run on
 * RuneLite's injected background executor, never on the client thread.
 */
@Slf4j
@PluginDescriptor(
	name = "Boss Lab",
	// Names the plugin's data directory, .runelite/plugin-data/boss-lab. Changing it
	// later would orphan a player's logs.
	internalName = "boss-lab",
	description = "Records boss runs to local files for later analysis. Records only; "
		+ "shows nothing during a fight.",
	tags = {"boss", "log", "data", "doom", "mokhaiotl", "analytics"}
)
public class BossLabPlugin extends Plugin
{
	private static final String VERSION = "0.2.1";

	@Inject
	private Client client;

	@Inject
	private BossLabConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private InventoryTracker tracker;

	@Inject
	private Gson gson;

	private final List<BossModule> modules = new ArrayList<>();
	private final List<RunRecorder> recorders = new ArrayList<>();
	private final List<JsonlWriter> writers = new ArrayList<>();

	private volatile BossLabPanel panel;
	private NavigationButton navButton;

	/** Set together, on the client thread. Read by the panel refresh from elsewhere. */
	private volatile int activeIndex = -1;
	private BossModule activeModule;
	private RunRecorder activeRecorder;

	private int lastPrayer = -1;
	private volatile int runsToday;

	@Provides
	BossLabConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossLabConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		// The directory RuneLite gives this plugin. Everything written goes under it,
		// through a path type that cannot reach anywhere else.
		Filepath base = getPluginDirectory();

		// One module per implemented boss. Adding a boss is adding to this list plus a
		// spec; nothing in core/ names a boss.
		register(new DoomModule(), base);

		panel = new BossLabPanel();
		BufferedImage icon = loadIcon();
		NavigationButton.NavigationButtonBuilder b = NavigationButton.builder()
			.tooltip("Boss Lab")
			.priority(7)
			.panel(panel);
		if (icon != null)
		{
			b.icon(icon);
		}
		navButton = b.build();
		clientToolbar.addNavigation(navButton);

		applyConfig();
		updatePanel();

		// Housekeeping that should not wait for the first run of a session: a month
		// that ended while the client was closed still needs compressing.
		final int keep = config.keepRawMonths();
		final List<JsonlWriter> all = new ArrayList<>(writers);
		executor.execute(() -> {
			for (JsonlWriter w : all)
			{
				w.rotate();
				w.prune(keep);
			}
		});
		refreshCounts();
	}

	@Override
	protected void shutDown()
	{
		// A run still open when the plugin stops is not thrown away.
		endOpenRuns("logout");
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		modules.clear();
		recorders.clear();
		writers.clear();
		deactivate();
		panel = null;
	}

	private void register(BossModule module, Filepath base)
	{
		BossSpec spec;
		try
		{
			spec = BossSpec.load(gson, module.bossId());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("boss lab: no usable spec for {}, skipping that boss", module.bossId(), e);
			return;
		}
		JsonlWriter writer = new JsonlWriter(base, module.bossId(), gson);
		RunRecorder recorder = new RunRecorder(client, tracker, spec, writer, executor,
			VERSION, written -> refreshCounts());
		modules.add(module);
		writers.add(writer);
		recorders.add(recorder);
	}

	private void applyConfig()
	{
		for (RunRecorder r : recorders)
		{
			r.setCaptureMode(config.captureMode());
			r.setKeepMonths(config.keepRawMonths());
		}
	}

	private void endOpenRuns(String outcome)
	{
		for (RunRecorder r : recorders)
		{
			if (r.runOpen())
			{
				r.endRun(outcome);
			}
		}
	}

	// ---- which boss is active ----------------------------------------
	private void activate(int index)
	{
		activeModule = modules.get(index);
		activeRecorder = recorders.get(index);
		activeIndex = index;
		lastPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
		activeModule.onEnterArea(activeRecorder);
		updatePanel();
	}

	private void deactivate()
	{
		activeModule = null;
		activeRecorder = null;
		activeIndex = -1;
		lastPrayer = -1;
	}

	private boolean active()
	{
		return activeModule != null && activeRecorder != null && config.loggingEnabled();
	}

	// ---- events ------------------------------------------------------
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BossLabConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		// Without this a setting only took effect after a restart, so capture mode
		// could be switched on for a session and record nothing.
		applyConfig();
		updatePanel();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			endOpenRuns("logout");
			if (activeModule != null)
			{
				activeModule.onLeaveArea(activeRecorder);
			}
			deactivate();
			updatePanel();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!config.loggingEnabled())
		{
			if (activeModule != null)
			{
				// Switched off part-way: what was recorded so far is still written.
				endOpenRuns("unknown");
				activeModule.onLeaveArea(activeRecorder);
				deactivate();
				updatePanel();
			}
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		if (activeModule == null)
		{
			// A boss with a fixed location is found by where the player stands. Nothing
			// is recorded outside a boss area, so no location elsewhere is ever kept.
			WorldView view = client.getTopLevelWorldView();
			int[] regions = view == null ? new int[0] : view.getMapRegions();
			for (int i = 0; i < modules.size(); i++)
			{
				if (modules.get(i).isInArea(local.getWorldLocation(), regions))
				{
					activate(i);
					break;
				}
			}
			if (activeModule == null)
			{
				return;
			}
		}

		activeModule.onTick(activeRecorder);

		WorldView view = client.getTopLevelWorldView();
		int[] regions = view == null ? new int[0] : view.getMapRegions();
		if (!activeModule.isInArea(local.getWorldLocation(), regions))
		{
			activeModule.onLeaveArea(activeRecorder);
			if (activeRecorder.runOpen())
			{
				activeRecorder.endRun("unknown");
			}
			deactivate();
			updatePanel();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.loggingEnabled())
		{
			return;
		}
		// Only messages from the game itself. Nothing another player says is ever read.
		switch (event.getType())
		{
			case GAMEMESSAGE:
			case SPAM:
			case MESBOX:
				break;
			default:
				return;
		}

		// A boss can be instanced, so its region is not fixed and a message may be the
		// first sign the player is there. A module that recognises its own boss
		// latches on and takes over from here.
		if (activeModule == null)
		{
			for (int i = 0; i < modules.size(); i++)
			{
				if (modules.get(i).probeChat(event))
				{
					activate(i);
					break;
				}
			}
		}
		if (activeModule != null)
		{
			activeModule.onChatMessage(event, activeRecorder);
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (!config.loggingEnabled())
		{
			return;
		}
		// Only the id is looked at, to recognise a boss. Nothing else about the NPC.
		int id = event.getNpc().getId();
		if (activeModule == null)
		{
			for (int i = 0; i < modules.size(); i++)
			{
				if (modules.get(i).probeNpc(id, recorders.get(i)))
				{
					activate(i);
					break;
				}
			}
		}
		if (activeModule != null)
		{
			activeModule.onNpcSpawned(id, activeRecorder);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!config.loggingEnabled())
		{
			return;
		}
		if (activeModule == null)
		{
			for (int i = 0; i < modules.size(); i++)
			{
				if (modules.get(i).probeWidget(event.getGroupId(), recorders.get(i)))
				{
					activate(i);
					break;
				}
			}
		}
		if (activeModule != null)
		{
			activeModule.onWidgetLoaded(event, activeRecorder);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		// An interface that is closed only to be rebuilt at once has not gone anywhere.
		if (active() && event.isUnload())
		{
			activeModule.onWidgetClosed(event.getGroupId(), activeRecorder);
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		// Fires constantly, so this must stay a null check and one comparison.
		if (activeModule != null)
		{
			activeModule.onScript(event.getScriptId(), activeRecorder);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (active())
		{
			activeModule.onVarbitChanged(event, activeRecorder);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (activeRecorder == null || !activeRecorder.runOpen())
		{
			return;
		}
		// Only damage to the local player, so nothing about anyone else is recorded.
		// A heal arrives as a hitsplat too, and is not damage.
		if (event.getActor() == client.getLocalPlayer()
			&& event.getHitsplat().getHitsplatType() != HitsplatID.HEAL)
		{
			activeRecorder.addDamageTaken(event.getHitsplat().getAmount());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (active() && event.getActor() == client.getLocalPlayer())
		{
			activeModule.onDeath(activeRecorder);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.PRAYER)
		{
			return;
		}
		// Prayer points draining is the boosted level falling. A rise is a restore or
		// a level, and only moves the baseline.
		int now = event.getBoostedLevel();
		if (lastPrayer >= 0 && now < lastPrayer
			&& activeRecorder != null && activeRecorder.runOpen())
		{
			activeRecorder.addPrayerUsed(lastPrayer - now);
		}
		lastPrayer = now;
	}

	// ---- panel -------------------------------------------------------
	private void refreshCounts()
	{
		final List<JsonlWriter> all = new ArrayList<>(writers);
		executor.execute(() -> {
			int total = 0;
			for (JsonlWriter w : all)
			{
				total += w.countToday();
			}
			runsToday = total;
			updatePanel();
		});
	}

	/** Safe from any thread: it reads only snapshots and the panel hops to Swing itself. */
	private void updatePanel()
	{
		BossLabPanel p = panel;
		if (p == null)
		{
			return;
		}
		int index = activeIndex;
		JsonlWriter writer = null;
		RunRecorder recorder = null;
		try
		{
			if (index >= 0)
			{
				writer = writers.get(index);
				recorder = recorders.get(index);
			}
			else if (!writers.isEmpty())
			{
				writer = writers.get(0);
			}
		}
		catch (RuntimeException e)
		{
			// The plugin was shut down between the two reads. Nothing to show.
			return;
		}
		p.setFolder(writer == null ? null : writer.directory());
		p.update(
			config.loggingEnabled(),
			recorder != null && recorder.runOpen(),
			recorder == null ? null : recorder.spec().name,
			writer == null ? null : writer.currentFile().getFileName(),
			runsToday,
			config.captureMode());
	}

	private BufferedImage loadIcon()
	{
		try
		{
			return ImageUtil.loadImageResource(BossLabPlugin.class, "panel-icon.png");
		}
		catch (RuntimeException e)
		{
			log.debug("boss lab: no panel icon, using the default");
			return null;
		}
	}
}

package io.github.giwasawa.bosslab.bosses.doom;

import io.github.giwasawa.bosslab.core.BossModule;
import io.github.giwasawa.bosslab.core.BossSpec;
import io.github.giwasawa.bosslab.core.RunContext;
import java.util.Collections;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.util.Text;

/**
 * Doom of Mokhaiotl.
 *
 * <p>A run is a sequence of delves. The player chooses how deep to push, and a run ends
 * when they claim the loot and leave, die, or go. Delves are recorded with their real
 * number and no cap: a deep delve past 8 keeps its own number and carries the
 * scoreboard's "8+" label alongside it.
 *
 * <p>What each signal means here, and how far it can be trusted:
 * <ul>
 *   <li><b>The boss appears.</b> A delve has begun, and a run if none was open. This is
 *       what lets the first delve's supplies be measured at all.</li>
 *   <li><b>The end-of-delve interface opens</b>, titled "Level N Complete!". Delve N is
 *       cleared, and the interface's loot pile says what the run has earned so far.
 *       RuneLite's own loot tracker reads the same title and the same pile.</li>
 *   <li><b>A "Delve level: N duration" line.</b> Also delve N cleared, with the game's
 *       own timing. Its wording is unconfirmed, so nothing depends on it alone.</li>
 *   <li><b>That interface closes</b> without a claim. The player descended, so the next
 *       delve has begun.</li>
 *   <li><b>The loot-claim script runs.</b> The run ended in a claim. RuneLite's loot
 *       tracker and screenshot plugin key off the same script.</li>
 *   <li><b>The player dies.</b> The run ended in a death, in the delve being fought.</li>
 * </ul>
 * Clears can be announced twice, and a boss can appear when no delve is starting, so
 * every one of these is safe to receive out of order or more than once.
 *
 * <p>The delves are instanced, so there is no fixed region to test. The module latches
 * onto the area at the first of those signals and lets go when the player is seen to
 * have left the instance, or after a long quiet spell.
 *
 * <p>Nothing about the fight is interpreted and nothing is shown.
 */
public class DoomModule implements BossModule
{
	/** Ticks of quiet after which we assume the player has left. 500 ticks is ~5 minutes. */
	private static final int QUIET_TICKS = 500;

	/** Ticks outside any instance before the player is taken to have left the delves. */
	private static final int OUTSIDE_TICKS = 10;

	/**
	 * How long a death waits for a reclaim fee line before the run is written. The fee
	 * can only be attached while the run is still open.
	 */
	private static final int FEE_GRACE_TICKS = 50;

	/** The title of the end-of-delve interface: "Level 2 Complete!". */
	private static final Pattern LEVEL = Pattern.compile("Level\\s+(\\d+)");

	/** A gp figure in the chest's value text, however it is worded or punctuated. */
	private static final Pattern GP = Pattern.compile("([0-9][0-9,\\s]*)");

	/**
	 * A reclaim fee line, should one appear. Not in the spec because it is not specific
	 * to this boss and the wording is unconfirmed; capture mode will show the real text.
	 */
	private static final Pattern FEE = Pattern.compile(
		"(?:reclaim|retrieve)[^0-9]{0,40}([0-9][0-9,]*)\\s*(?:gp|coins)"
			+ "|([0-9][0-9,]*)\\s*(?:gp|coins)[^0-9]{0,40}(?:reclaim|retrieve)",
		Pattern.CASE_INSENSITIVE);

	private boolean inArea;
	private int lastSeenTick;

	/** Game ids, copied out of the spec once so the per-script check is one comparison. */
	private boolean bound;
	private Set<Integer> bossNpcs = Collections.emptySet();
	private Set<Integer> watchedVarps = Collections.emptySet();
	private int chestGroup = -1;
	private int claimScript = -1;

	/** True from the end-of-delve interface opening until it closes. */
	private boolean chestOpen;

	/**
	 * Whether the chest is waiting to be read, and the tick it appeared on.
	 *
	 * <p>A widget is not built when {@code WidgetLoaded} fires, so its children hold no
	 * text or items yet. The read is deferred to the next tick. The flag is separate
	 * from the tick because tick 0 is a real value.
	 */
	private boolean chestPending;
	private int chestLoadedTick;

	/** Tick of a death whose run is still open, waiting on a fee line. -1 when none. */
	private int deathTick = -1;

	/**
	 * Whether the delves were seen to be instanced, learned from where the boss and the
	 * chest actually showed up rather than assumed. Only then does leaving an instance
	 * mean leaving the delves.
	 */
	private boolean arenaIsInstance;
	private int outsideTicks;

	@Override
	public String bossId()
	{
		return "doom-of-mokhaiotl";
	}

	@Override
	public boolean isInArea(WorldPoint point, int[] mapRegions)
	{
		return inArea;
	}

	// ---- recognising the area ----------------------------------------
	@Override
	public boolean probeChat(ChatMessage event)
	{
		// Any of this boss's own lines identifies it. The delve lines are unmistakable.
		String msg = plain(event);
		return msg != null
			&& (msg.startsWith("Delve level") || msg.startsWith("Deep delves completed"));
	}

	@Override
	public boolean probeNpc(int npcId, RunContext ctx)
	{
		bind(ctx.spec());
		return bossNpcs.contains(npcId);
	}

	@Override
	public boolean probeWidget(int groupId, RunContext ctx)
	{
		bind(ctx.spec());
		return groupId == chestGroup;
	}

	private void bind(BossSpec spec)
	{
		if (bound)
		{
			return;
		}
		bound = true;
		BossSpec.Ids ids = spec.ids;
		bossNpcs = BossSpec.Ids.known(ids.npcs);
		watchedVarps = BossSpec.Ids.known(ids.varps);
		Integer group = ids.widget("loot_chest_group");
		chestGroup = group == null ? -1 : group;
		Integer script = ids.script("loot_claim");
		claimScript = script == null ? -1 : script;
	}

	/**
	 * A message with the game's own markup removed.
	 *
	 * <p>Game messages arrive carrying colour and formatting tags, so matching the raw
	 * text would fail against any line the game happens to colour.
	 */
	private static String plain(ChatMessage event)
	{
		String msg = event.getMessage();
		return msg == null ? null : Text.removeTags(msg).trim();
	}

	@Override
	public void onEnterArea(RunContext ctx)
	{
		bind(ctx.spec());
		inArea = true;
		chestOpen = false;
		chestPending = false;
		deathTick = -1;
		arenaIsInstance = false;
		outsideTicks = 0;
		lastSeenTick = ctx.tick();

		// While a boss is being set up, open a run straight away so captured ids have
		// somewhere to go even if no other signal ever matches. That case is exactly
		// what capture mode exists to diagnose.
		if (ctx.capturing() && !ctx.runOpen())
		{
			ctx.startRun();
		}
	}

	@Override
	public void onLeaveArea(RunContext ctx)
	{
		inArea = false;
		chestOpen = false;
		chestPending = false;
		deathTick = -1;
		arenaIsInstance = false;
		outsideTicks = 0;
	}

	// ---- the boss appearing: a delve begins --------------------------
	@Override
	public void onNpcSpawned(int npcId, RunContext ctx)
	{
		if (!bossNpcs.contains(npcId))
		{
			if (ctx.capturing())
			{
				ctx.capture("npc", npcId, null);
			}
			return;
		}
		lastSeenTick = ctx.tick();
		arenaIsInstance = ctx.inInstance();
		outsideTicks = 0;

		if (deathTick >= 0)
		{
			// A new attempt has started, so the fee line is not coming.
			ctx.endRun("death");
			deathTick = -1;
		}
		if (chestOpen)
		{
			// The delve is over and the player has not chosen yet. Not a new delve.
			return;
		}
		if (!ctx.runOpen())
		{
			ctx.startRun();
		}
		// Harmless when a delve is already open: the boss changes form mid-fight.
		ctx.beginBoundary(ctx.lastClosedBoundary() + 1);
	}

	// ---- the end-of-delve interface: a delve is cleared --------------
	@Override
	public void onWidgetLoaded(WidgetLoaded event, RunContext ctx)
	{
		if (event.getGroupId() == chestGroup)
		{
			lastSeenTick = ctx.tick();
			arenaIsInstance = ctx.inInstance();
			outsideTicks = 0;
			chestOpen = true;
			chestPending = true;
			chestLoadedTick = ctx.tick();
			return;
		}
		if (ctx.capturing())
		{
			ctx.capture("widget", event.getGroupId(), null);
		}
	}

	@Override
	public void onWidgetClosed(int groupId, RunContext ctx)
	{
		if (groupId != chestGroup)
		{
			return;
		}
		if (chestPending)
		{
			// Opened and closed within a tick. Read what is still readable.
			chestPending = false;
			readChest(ctx);
		}
		chestOpen = false;
		// A claim ends the run before the interface closes. So if a run is still open
		// here, the player descended, and the next delve starts now.
		if (ctx.runOpen() && deathTick < 0 && ctx.lastClosedBoundary() > 0)
		{
			ctx.beginBoundary(ctx.lastClosedBoundary() + 1);
		}
	}

	/**
	 * Read the chest once it has been built.
	 *
	 * <p>Its title names the delve just cleared. Its pile is the run's loot so far, so
	 * the core records only what this delve added. Its own "Value: X GP" total is kept
	 * too, because a death shows no chest at all and that figure is then the only
	 * statement of what was forfeited.
	 */
	private void readChest(RunContext ctx)
	{
		BossSpec.Ids ids = ctx.spec().ids;

		Integer frame = ids.widget("loot_chest_frame");
		Integer level = frame == null ? null : parseLevel(ctx.widgetChildText(frame, 1));
		int last = ctx.lastClosedBoundary();
		if (level == null)
		{
			// The title could not be read. The delve being fought is the best answer;
			// failing that, the chest is showing the one already closed.
			level = ctx.boundaryOpen() ? ctx.currentBoundary() : last;
			if (ctx.capturing() && frame != null)
			{
				ctx.capture("widget", frame, "title unreadable");
			}
		}
		if (level > 0)
		{
			if (level == last)
			{
				// Already closed, by the chat line or an earlier look at this chest. A
				// delve begun since then was begun too soon.
				ctx.cancelBoundary();
			}
			else
			{
				ctx.closeBoundary(level, ctx.spec().labelFor(level), true);
			}
		}

		readPile(ctx, ids);

		Integer valueId = ids.widget("loot_chest_value");
		if (valueId != null)
		{
			String text = ctx.widgetText(valueId);
			Integer gp = parseGp(text);
			if (gp != null)
			{
				ctx.recordChestValue(gp);
			}
			else if (ctx.capturing())
			{
				// Record the raw text so the parser can be corrected from it.
				ctx.capture("widget", valueId, text);
			}
		}
	}

	/** The loot pile, from whichever source has it. */
	private void readPile(RunContext ctx, BossSpec.Ids ids)
	{
		String source = null;
		for (String key : new String[]{"loot_pile", "loot_pile_during"})
		{
			Integer inventory = ids.inventory(key);
			if (inventory != null && ctx.recordLootPile(inventory) > 0)
			{
				source = key;
				break;
			}
		}
		if (source == null)
		{
			Integer contents = ids.widget("loot_chest_contents");
			if (contents != null && ctx.recordLootFromWidget(contents) > 0)
			{
				source = "loot_chest_contents";
			}
		}
		if (ctx.capturing())
		{
			ctx.capture("widget", chestGroup,
				source == null ? "loot pile empty everywhere" : "loot pile read from " + source);
		}
	}

	static Integer parseLevel(String title)
	{
		if (title == null)
		{
			return null;
		}
		Matcher m = LEVEL.matcher(Text.removeTags(title));
		if (!m.find())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(m.group(1));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * Pull a gp figure out of the chest's value text.
	 *
	 * <p>The exact wording is unconfirmed, so this takes the first run of digits with
	 * separators stripped rather than assuming a format. Returns null if there is none,
	 * so a wording change records nothing instead of something wrong.
	 */
	static Integer parseGp(String text)
	{
		if (text == null)
		{
			return null;
		}
		Matcher m = GP.matcher(Text.removeTags(text));
		if (!m.find())
		{
			return null;
		}
		try
		{
			long value = Long.parseLong(m.group(1).replaceAll("[,\\s]", ""));
			return value > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) value;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	// ---- the claim script: the run ends in a claim -------------------
	@Override
	public void onScript(int scriptId, RunContext ctx)
	{
		if (scriptId != claimScript || !ctx.runOpen() || deathTick >= 0)
		{
			return;
		}
		lastSeenTick = ctx.tick();
		if (chestPending)
		{
			chestPending = false;
			readChest(ctx);
		}
		else
		{
			// One last look, so the claim is the full pile even if a chest was missed.
			Integer pileId = ctx.spec().ids.inventory("loot_pile");
			if (pileId != null)
			{
				ctx.recordLootPile(pileId);
			}
		}
		ctx.endRun("claim");
	}

	// ---- death -------------------------------------------------------
	@Override
	public void onDeath(RunContext ctx)
	{
		if (!ctx.runOpen() || deathTick >= 0)
		{
			return;
		}
		// A death forfeits every drop of the run. There is no chest interface at all:
		// the value goes to zero, less the reclaim fee. Confirmed in game 2026-11-26.
		// So the loss is whatever the last chest showed, which the core carried forward.
		int delve = ctx.boundaryOpen() ? ctx.currentBoundary() : ctx.lastClosedBoundary() + 1;
		ctx.closeBoundary(delve, ctx.spec().labelFor(delve), false);
		// The run stays open a little longer so a fee line can still be attached.
		deathTick = ctx.tick();
		lastSeenTick = ctx.tick();
		chestPending = false;
		chestOpen = false;
	}

	// ---- every tick --------------------------------------------------
	@Override
	public void onTick(RunContext ctx)
	{
		int tick = ctx.tick();
		if (chestPending && tick > chestLoadedTick)
		{
			chestPending = false;
			readChest(ctx);
		}

		if (deathTick >= 0 && tick - deathTick > FEE_GRACE_TICKS)
		{
			ctx.endRun("death");
			deathTick = -1;
		}

		if (ctx.capturing() && ctx.runOpen())
		{
			ctx.captureRegion();
		}

		if (arenaIsInstance && deathTick < 0)
		{
			if (ctx.inInstance())
			{
				outsideTicks = 0;
				lastSeenTick = tick;
			}
			else if (++outsideTicks > OUTSIDE_TICKS)
			{
				// Gone, with neither a claim nor a death: a teleport out.
				leave(ctx);
				return;
			}
		}

		// The fallback, for when nothing said the player left.
		if (inArea && deathTick < 0 && tick - lastSeenTick > QUIET_TICKS)
		{
			leave(ctx);
		}
	}

	private void leave(RunContext ctx)
	{
		if (ctx.runOpen())
		{
			ctx.endRun("unknown");
		}
		onLeaveArea(ctx);
	}

	// ---- chat --------------------------------------------------------
	@Override
	public void onChatMessage(ChatMessage event, RunContext ctx)
	{
		String msg = plain(event);
		if (msg == null || msg.isEmpty())
		{
			return;
		}
		lastSeenTick = ctx.tick();
		BossSpec spec = ctx.spec();

		if (ctx.capturing())
		{
			// Record the exact wording of every game message in the area while setting
			// up, matched or not. A pattern that matches the wrong thing is as much a
			// problem as one that matches nothing, and only the raw text shows which.
			// The raw form is kept, markup and all, since that is what has to be
			// matched against in the end.
			ctx.capture("chat", null, event.getMessage());
		}

		if (deathTick >= 0)
		{
			Matcher fee = FEE.matcher(msg);
			if (fee.find())
			{
				try
				{
					String figure = fee.group(1) != null ? fee.group(1) : fee.group(2);
					ctx.recordDeathFee(Integer.parseInt(figure.replace(",", "")));
				}
				catch (NumberFormatException ignored)
				{
					// Not a number we understand; better to record nothing than a wrong fee.
				}
				ctx.endRun("death");
				deathTick = -1;
			}
			return;
		}

		if (matchDelveComplete(msg, ctx, spec))
		{
			return;
		}
		if (matchRunComplete(msg, ctx, spec))
		{
			return;
		}
		if (matchDeepDelves(msg, ctx, spec))
		{
			return;
		}
		matchPet(msg, ctx, spec);
	}

	/** "Delve level: N duration: m:ss. Personal best: m:ss" */
	private boolean matchDelveComplete(String msg, RunContext ctx, BossSpec spec)
	{
		Matcher m = matcher(spec, "delve_complete", msg);
		if (m == null)
		{
			return false;
		}
		int delve;
		try
		{
			delve = Integer.parseInt(m.group("delve"));
		}
		catch (RuntimeException e)
		{
			return false;
		}
		Double duration = seconds(group(m, "duration"));
		Double pb = seconds(group(m, "pb"));
		// A death never produces this line, so reaching here means the delve was
		// cleared. The chest says the same thing; whichever arrives second is ignored.
		ctx.closeBoundary(delve, spec.labelFor(delve), true);
		if (duration != null)
		{
			ctx.recordPb(delve, duration, pb, pb != null && duration <= pb);
		}
		return true;
	}

	/** "Delve level 1 - 8 duration: m:ss. Personal best: m:ss" */
	private boolean matchRunComplete(String msg, RunContext ctx, BossSpec spec)
	{
		Matcher m = matcher(spec, "run_complete", msg);
		if (m == null)
		{
			return false;
		}
		Double duration = seconds(group(m, "duration"));
		Double pb = seconds(group(m, "pb"));
		if (duration != null && ctx.runOpen())
		{
			ctx.recordPb("1-8", duration, pb, pb != null && duration <= pb);
		}
		// This is a split for the first eight delves, not the end of the run: the player
		// may still be descending. So the run is left open.
		return true;
	}

	private boolean matchDeepDelves(String msg, RunContext ctx, BossSpec spec)
	{
		Matcher m = matcher(spec, "deep_delves", msg);
		if (m == null)
		{
			return false;
		}
		try
		{
			ctx.recordDeepDelves(Integer.parseInt(m.group("count")));
		}
		catch (RuntimeException ignored)
		{
			// Matched but unreadable; nothing to record.
		}
		return true;
	}

	private boolean matchPet(String msg, RunContext ctx, BossSpec spec)
	{
		for (String key : new String[]{"pet", "pet_backpack"})
		{
			if (matcher(spec, key, msg) != null)
			{
				// A unique is recorded the moment it appears, even if the run then dies.
				ctx.recordUnique("pet");
				return true;
			}
		}
		return false;
	}

	// ---- capture mode: values worth checking against a real run ------
	@Override
	public void onVarbitChanged(VarbitChanged event, RunContext ctx)
	{
		if (ctx.capturing() && watchedVarps.contains(event.getVarpId()))
		{
			ctx.capture("varp", event.getVarpId(), Integer.toString(event.getValue()));
		}
	}

	// ---- helpers -----------------------------------------------------
	/** A matcher that found the pattern, or null. */
	private static Matcher matcher(BossSpec spec, String key, String msg)
	{
		BossSpec.ChatPattern p = spec.pattern(key);
		if (p == null || p.compiled() == null)
		{
			return null;
		}
		Matcher m = p.compiled().matcher(msg);
		return m.find() ? m : null;
	}

	private static String group(Matcher m, String name)
	{
		try
		{
			return m.group(name);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** "m:ss" or "m:ss.ff" to seconds. Null when absent or unparseable. */
	static Double seconds(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}
		int colon = text.indexOf(':');
		if (colon < 0)
		{
			return null;
		}
		try
		{
			int minutes = Integer.parseInt(text.substring(0, colon));
			double secs = Double.parseDouble(text.substring(colon + 1));
			return minutes * 60 + secs;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package io.github.giwasawa.bosslab.core;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BossLabConfig.GROUP)
public interface BossLabConfig extends Config
{
	String GROUP = "bosslab";

	@ConfigSection(
		name = "Logging",
		description = "What gets written to disk",
		position = 0
	)
	String loggingSection = "logging";

	@ConfigSection(
		name = "Setting up a boss",
		description = "Only needed once per boss, to map its game ids",
		position = 10,
		closedByDefault = true
	)
	String setupSection = "setup";

	@ConfigItem(
		keyName = "loggingEnabled",
		name = "Record runs",
		description = "Write a line to a local file for each boss run. Nothing is sent anywhere.",
		section = loggingSection,
		position = 1
	)
	default boolean loggingEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "keepRawMonths",
		name = "Keep raw events for",
		description = "Months of per-delve detail to keep. 0 keeps everything forever. "
			+ "Older months keep their run summaries either way.",
		section = loggingSection,
		position = 2
	)
	default int keepRawMonths()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "captureMode",
		name = "Capture unmapped ids",
		description = "Records the widget, chat, animation and object ids seen inside the "
			+ "boss area so they can be added to the boss spec. Makes log files much "
			+ "larger, so turn it off once a boss is mapped.",
		section = setupSection,
		position = 1,
		warning = "Capture mode writes every game id it sees inside the boss area into "
			+ "your log files, which makes them much larger. It is meant for a few runs "
			+ "while a boss is being set up, not for everyday play. Turn it on?"
	)
	default boolean captureMode()
	{
		return false;
	}
}

package io.github.giwasawa.bosslab.core;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;

/**
 * The plugin's only user interface.
 *
 * <p>Deliberately almost empty. Section 2.1 is non-negotiable: this plugin never helps
 * during a fight. No overlay, no timer, no counter, no cue, no prediction, no
 * highlighting, no menu entry. It shows logging status and where the log folder is, with a
 * button that copies that path. It does not open the folder: Plugin Hub plugins may not
 * start other programs, and a file manager is one.
 *
 * <p>No live combat statistics appear here, not even between runs, in version 1.
 */
public class BossLabPanel extends PluginPanel
{
	private final JLabel state = new JLabel();
	private final JLabel boss = new JLabel();
	private final JLabel file = new JLabel();
	private final JLabel today = new JLabel();
	private final JLabel capture = new JLabel();

	private final JTextArea path = new JTextArea();

	public BossLabPanel()
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel rows = new JPanel(new GridLayout(0, 1, 0, 6));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (JLabel l : new JLabel[]{state, boss, file, today, capture})
		{
			rows.add(l);
		}

		JLabel note = new JLabel("<html><body style='width:170px'>"
			+ "Records runs to local files for later analysis. "
			+ "Nothing is shown during a fight and nothing is sent anywhere."
			+ "</body></html>");
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		path.setEditable(false);
		path.setLineWrap(true);
		path.setWrapStyleWord(false);
		path.setFont(note.getFont());
		path.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		path.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		path.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		path.setToolTipText("The folder these logs are written to");

		// Plugins may not start other programs, which is what opening a file manager
		// is. So the folder is shown, and can be copied, instead of opened.
		JButton copy = new JButton("Copy folder path");
		copy.setToolTipText("Copy the log folder's path, to paste into Explorer or Finder");
		copy.addActionListener(e -> {
			String text = path.getText();
			if (!text.isEmpty())
			{
				Toolkit.getDefaultToolkit().getSystemClipboard()
					.setContents(new StringSelection(text), null);
			}
		});
		copy.setPreferredSize(new Dimension(0, 30));

		JPanel where = new JPanel(new BorderLayout(0, 6));
		where.setBackground(ColorScheme.DARK_GRAY_COLOR);
		where.add(path, BorderLayout.NORTH);
		where.add(copy, BorderLayout.CENTER);

		JPanel top = new JPanel(new BorderLayout(0, 8));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(rows, BorderLayout.NORTH);
		top.add(note, BorderLayout.CENTER);

		add(top, BorderLayout.NORTH);
		add(where, BorderLayout.CENTER);
	}

	/** Called from any thread; hops to the Swing thread itself. */
	public void setFolder(Filepath folder)
	{
		String text = folder == null ? "" : folder.toString();
		SwingUtilities.invokeLater(() -> {
			if (!text.equals(path.getText()))
			{
				path.setText(text);
			}
		});
	}

	/** Called from any thread; hops to the Swing thread itself. */
	public void update(boolean enabled, boolean recording, String bossName,
					   String currentFile, int runsToday, boolean capturing)
	{
		SwingUtilities.invokeLater(() -> {
			state.setText(!enabled ? "Logging: off"
				: recording ? "Logging: recording a run" : "Logging: on, waiting");
			boss.setText("Boss: " + (bossName == null ? "none in range" : bossName));
			file.setText("File: " + (currentFile == null ? "-" : currentFile));
			today.setText("Runs logged today: " + runsToday);
			capture.setText(capturing ? "Capture mode: on" : "");
			capture.setForeground(capturing ? ColorScheme.PROGRESS_INPROGRESS_COLOR
				: ColorScheme.LIGHT_GRAY_COLOR);
		});
	}
}

package io.github.giwasawa.bosslab.core;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;

/**
 * Everything boss-specific lives behind this interface.
 *
 * <p>Nothing in {@code core/} names a particular boss. A module decides where the boss
 * is and what its events mean; the core owns the session, the snapshots, pricing, the
 * writer and the panel. Adding a boss means adding a module here plus a spec under
 * {@code bosses/<id>/}, an engine adapter and a dashboard tab.
 *
 * <p>Implementations must be cheap. Handlers run on the client thread, so they should
 * copy small values and hand everything else to the {@link RunContext}.
 */
public interface BossModule
{
	/** Boss id, matching the folder name under bosses/. */
	String bossId();

	/** True when this point is inside the boss area. Nothing is recorded outside it. */
	boolean isInArea(WorldPoint point, int[] mapRegions);

	/**
	 * Does this message identify this boss's area?
	 *
	 * <p>Needed because a boss can be instanced, so its region id is not fixed and
	 * {@link #isInArea} cannot recognise it from coordinates alone. The plugin offers
	 * every game message to every module while no module is active; a module that
	 * recognises its own boss latches on and {@link #isInArea} starts returning true.
	 *
	 * <p>Only messages from the game itself are offered here, never another player's.
	 */
	default boolean probeChat(ChatMessage event)
	{
		return false;
	}

	/**
	 * Does this NPC appearing identify this boss's area? Offered while no module is
	 * active, like {@link #probeChat}.
	 */
	default boolean probeNpc(int npcId, RunContext ctx)
	{
		return false;
	}

	/** Does this interface opening identify this boss's area? */
	default boolean probeWidget(int groupId, RunContext ctx)
	{
		return false;
	}

	/** Called when the player enters the area, before any run starts. */
	default void onEnterArea(RunContext ctx)
	{
	}

	/** Called when the player leaves the area. A run still open here ends as a logout. */
	default void onLeaveArea(RunContext ctx)
	{
	}

	default void onChatMessage(ChatMessage event, RunContext ctx)
	{
	}

	default void onWidgetLoaded(WidgetLoaded event, RunContext ctx)
	{
	}

	default void onWidgetClosed(int groupId, RunContext ctx)
	{
	}

	default void onVarbitChanged(VarbitChanged event, RunContext ctx)
	{
	}

	/** An NPC appeared near the player. Only its id is passed, nothing else about it. */
	default void onNpcSpawned(int npcId, RunContext ctx)
	{
	}

	/**
	 * A game script is about to run. Called for every script while in the area, which
	 * is a great many, so an implementation must be a single integer comparison.
	 */
	default void onScript(int scriptId, RunContext ctx)
	{
	}

	/** Once per tick while in the area. Keep this almost empty. */
	default void onTick(RunContext ctx)
	{
	}

	/** The local player died. The module decides what that means for the run. */
	default void onDeath(RunContext ctx)
	{
	}
}

package io.github.giwasawa.bosslab.core;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import lombok.extern.slf4j.Slf4j;

/**
 * A boss spec, as data.
 *
 * <p>Generated from {@code bosses/<id>/spec.yaml} by {@code tools/build_plugin_spec.py}
 * and bundled as a JSON resource, so the YAML stays the single source of truth and the
 * plugin needs no YAML dependency. RuneLite already provides Gson.
 *
 * <p>Nothing here is hard-coded in Java. A null game id means "not known yet", so the
 * plugin falls back to its other signals and degrades rather than breaking.
 */
@Slf4j
public class BossSpec
{
	public String id;
	public String name;
	public String version;

	@SerializedName("boundary_unit")
	public String boundaryUnit = "boundary";

	@SerializedName("rate_cap_at")
	public int rateCapAt = Integer.MAX_VALUE;

	@SerializedName("scoreboard_cap_label")
	public String scoreboardCapLabel;

	public List<Unique> uniques = new ArrayList<>();

	@SerializedName("untradeable_item_ids")
	public List<Integer> untradeableItemIds = new ArrayList<>();

	@SerializedName("untradeable_names")
	public List<String> untradeableNames = new ArrayList<>();

	@SerializedName("crafted_value")
	public List<CraftedValue> craftedValue = new ArrayList<>();

	@SerializedName("chat_patterns")
	public List<ChatPattern> chatPatterns = new ArrayList<>();

	public Ids ids = new Ids();

	private transient Set<Integer> untradeableSet;
	private transient Set<String> untradeableNameSet;

	public static class Unique
	{
		public String key;
		public String name;
		@SerializedName("item_id")
		public Integer itemId;
		@SerializedName("min_boundary")
		public Integer minBoundary;
		@SerializedName("is_pet")
		public boolean isPet;
	}

	/** An item whose worth is not its own price, such as the Mokhaiotl cloth. */
	public static class CraftedValue
	{
		public String key;
		@SerializedName("item_id")
		public int itemId;
		@SerializedName("output_item_id")
		public int outputItemId;
		public List<Part> subtract = new ArrayList<>();
		@SerializedName("ge_tax_rate")
		public double geTaxRate;
		@SerializedName("ge_tax_cap")
		public long geTaxCap;

		public static class Part
		{
			@SerializedName("item_id")
			public int itemId;
			public int qty;
		}
	}

	public static class ChatPattern
	{
		public String key;
		public String pattern;
		public boolean verified;
		private transient Pattern compiled;

		/** Null when the pattern does not compile, which is logged once and skipped. */
		public Pattern compiled()
		{
			if (compiled == null && pattern != null)
			{
				try
				{
					compiled = Pattern.compile(pattern);
				}
				catch (PatternSyntaxException e)
				{
					log.warn("boss spec chat pattern {} does not compile, skipping it", key, e);
					pattern = null;
				}
			}
			return compiled;
		}
	}

	/** Game ids. Everything is optional; null means capture mode has not mapped it yet. */
	public static class Ids
	{
		public List<Integer> regions = new ArrayList<>();
		public java.util.Map<String, Integer> widgets = Collections.emptyMap();
		public java.util.Map<String, Integer> varbits = Collections.emptyMap();
		public java.util.Map<String, Integer> objects = Collections.emptyMap();
		public java.util.Map<String, Integer> npcs = Collections.emptyMap();
		public java.util.Map<String, Integer> scripts = Collections.emptyMap();
		public java.util.Map<String, Integer> inventories = Collections.emptyMap();
		public java.util.Map<String, Integer> varps = Collections.emptyMap();

		public Integer widget(String key)
		{
			return widgets == null ? null : widgets.get(key);
		}

		public Integer varbit(String key)
		{
			return varbits == null ? null : varbits.get(key);
		}

		public Integer script(String key)
		{
			return scripts == null ? null : scripts.get(key);
		}

		public Integer inventory(String key)
		{
			return inventories == null ? null : inventories.get(key);
		}

		/** Every mapped id in a group, with the unmapped (null) ones left out. */
		public static Set<Integer> known(java.util.Map<String, Integer> group)
		{
			Set<Integer> out = new HashSet<>();
			if (group != null)
			{
				for (Integer id : group.values())
				{
					if (id != null)
					{
						out.add(id);
					}
				}
			}
			return out;
		}
	}

	// ---- loading ----------------------------------------------------
	public static BossSpec load(Gson gson, String bossId) throws IOException
	{
		// Relative to this class's own package, so it resolves the same whether the
		// plugin runs from classes on disk or from a packaged jar.
		String resource = "specs/" + bossId + ".json";
		try (InputStream in = BossSpec.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				throw new IOException("no bundled spec resource " + resource
					+ "; run tools/build_plugin_spec.py");
			}
			BossSpec spec = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), BossSpec.class);
			if (spec == null || spec.id == null)
			{
				throw new IOException("spec resource " + resource + " is empty or malformed");
			}
			return spec;
		}
	}

	// ---- queries ----------------------------------------------------
	public ChatPattern pattern(String key)
	{
		for (ChatPattern p : chatPatterns)
		{
			if (key.equals(p.key))
			{
				return p;
			}
		}
		return null;
	}

	public CraftedValue crafted(int itemId)
	{
		for (CraftedValue c : craftedValue)
		{
			if (c.itemId == itemId)
			{
				return c;
			}
		}
		return null;
	}

	/** Documented expectation only. The plugin still asks ItemComposition at runtime. */
	public boolean expectedUntradeable(int itemId)
	{
		if (untradeableSet == null)
		{
			untradeableSet = new HashSet<>(untradeableItemIds);
		}
		return untradeableSet.contains(itemId);
	}

	public boolean expectedUntradeableName(String name)
	{
		if (untradeableNameSet == null)
		{
			untradeableNameSet = new HashSet<>(untradeableNames);
		}
		return name != null && untradeableNameSet.contains(name);
	}

	/** The label the scoreboard uses for a boundary, so "8+" rides along with delve 11. */
	public String labelFor(int boundary)
	{
		if (scoreboardCapLabel != null && boundary >= rateCapAt)
		{
			return scoreboardCapLabel;
		}
		return Integer.toString(boundary);
	}

	public String uniqueKeyForItem(int itemId)
	{
		for (Unique u : uniques)
		{
			if (u.itemId != null && u.itemId == itemId)
			{
				return u.key;
			}
		}
		return null;
	}
}

package io.github.giwasawa.bosslab.core;

import io.github.giwasawa.bosslab.core.model.LoggedItem;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;

/**
 * Snapshots of what the player is carrying, and diffs between them.
 *
 * <p>Storage budget, section 2.4: a full snapshot at run start, then a diff at each
 * boundary. That keeps a run near 2-3 KB.
 *
 * <p>Potions are counted in doses, so a (4) becoming a (3) is one dose used, not one
 * item. Doses are read from the trailing "(N)" in the item's own name, so any potion
 * works with no lookup table to maintain.
 *
 * <p>Runs on the client thread only to read containers and varbits, which is cheap.
 * Everything else happens on the background executor.
 */
@Singleton
public class InventoryTracker
{
	/** A potion's dose count lives in its name, for example "Super restore(3)". */
	private static final Pattern DOSE = Pattern.compile("^(.*)\\((\\d)\\)$");

	/** The rune pouch's slots, including the divine pouch's extras. */
	private static final int[] POUCH_TYPE = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6,
	};
	private static final int[] POUCH_AMOUNT = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6,
	};

	private final Client client;
	private final Pricer pricer;

	@Inject
	public InventoryTracker(Client client, Pricer pricer)
	{
		this.client = client;
		this.pricer = pricer;
	}

	/**
	 * What the player holds, keyed so that the same thing in a different form lines up.
	 *
	 * <p>Two kinds of key. A plain item is keyed by its unnoted id, so 20 noted coal and
	 * 20 loose coal are the same row. A potion is keyed by its family name and counted in
	 * doses, so brews in any mix of (4), (3) and (2) add up to one total.
	 */
	public static class Snapshot
	{
		final Map<String, Entry> rows = new LinkedHashMap<>();

		static class Entry
		{
			int qty;            // items, or doses for a potion family
			int representativeId;
			int dosesPerItem;   // 1 for a plain item
			boolean noted;
		}

		boolean isEmpty()
		{
			return rows.isEmpty();
		}
	}

	// ---- reading -----------------------------------------------------
	public Snapshot inventory()
	{
		return fromContainer(client.getItemContainer(InventoryID.INV));
	}

	public Snapshot equipment()
	{
		return fromContainer(client.getItemContainer(InventoryID.WORN));
	}

	private Snapshot fromContainer(ItemContainer container)
	{
		Snapshot snap = new Snapshot();
		if (container == null)
		{
			return snap;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			add(snap, item.getId(), item.getQuantity());
		}
		return snap;
	}

	/**
	 * The rune pouch, read from its varbits.
	 *
	 * <p>This is the same data RuneLite's own rune pouch overlay uses, and it covers the
	 * divine pouch's extra slots. The type varbit is an index into a game enum, not an
	 * item id, so it is mapped through {@link EnumID#RUNEPOUCH_RUNE}.
	 */
	public Snapshot runePouch()
	{
		Snapshot snap = new Snapshot();
		EnumComposition runes;
		try
		{
			runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		}
		catch (RuntimeException e)
		{
			return snap;
		}
		if (runes == null)
		{
			return snap;
		}
		for (int slot = 0; slot < POUCH_TYPE.length; slot++)
		{
			int type = client.getVarbitValue(POUCH_TYPE[slot]);
			int amount = client.getVarbitValue(POUCH_AMOUNT[slot]);
			if (type <= 0 || amount <= 0)
			{
				continue;
			}
			int itemId;
			try
			{
				itemId = runes.getIntValue(type);
			}
			catch (RuntimeException e)
			{
				continue;
			}
			if (itemId > 0)
			{
				add(snap, itemId, amount);
			}
		}
		return snap;
	}

	private void add(Snapshot snap, int itemId, int qty)
	{
		ItemComposition comp = pricer.composition(itemId);

		boolean noted = false;
		int canonical = itemId;
		if (comp != null && comp.getNote() != -1)
		{
			// A noted stack is the same goods as the loose item, so count them together.
			noted = true;
			int linked = comp.getLinkedNoteId();
			if (linked > 0)
			{
				canonical = linked;
				comp = pricer.composition(canonical);
			}
		}

		String name = comp == null ? null : comp.getName();
		int doses = 1;
		String key = "item:" + canonical;
		if (name != null)
		{
			Matcher m = DOSE.matcher(name);
			if (m.matches())
			{
				doses = Integer.parseInt(m.group(2));
				key = "dose:" + m.group(1).trim();
			}
		}

		Snapshot.Entry e = snap.rows.get(key);
		if (e == null)
		{
			e = new Snapshot.Entry();
			e.representativeId = canonical;
			e.dosesPerItem = doses;
			e.noted = noted;
			snap.rows.put(key, e);
		}
		e.qty += qty * doses;
		// Keep the fullest variant as the one we log, so the price we divide is the
		// price of a full potion rather than a nearly empty one.
		if (doses > e.dosesPerItem)
		{
			e.representativeId = canonical;
			e.dosesPerItem = doses;
		}
	}

	/**
	 * One stack of loot, priced now.
	 *
	 * <p>A noted stack is logged against the loose item, which is the one that carries a
	 * price. Loot is counted in items, never doses: it is what the chest showed.
	 */
	public LoggedItem lootItem(BossSpec spec, int itemId, int qty)
	{
		ItemComposition comp = pricer.composition(itemId);
		boolean noted = false;
		int canonical = itemId;
		if (comp != null && comp.getNote() != -1)
		{
			noted = true;
			int linked = comp.getLinkedNoteId();
			if (linked > 0)
			{
				canonical = linked;
			}
		}
		return pricer.price(spec, canonical, qty, noted);
	}

	// ---- pricing a snapshot or a diff --------------------------------
	public List<LoggedItem> toLogged(BossSpec spec, Snapshot snap)
	{
		List<LoggedItem> out = new ArrayList<>();
		for (Snapshot.Entry e : snap.rows.values())
		{
			if (e.qty != 0)
			{
				out.add(logged(spec, e, e.qty));
			}
		}
		return out;
	}

	/**
	 * What changed between two snapshots.
	 *
	 * <p>Negative quantities are consumption, which is what a supply cost is made of.
	 * Positive ones are things that arrived, usually loot, already counted at the chest.
	 */
	public List<LoggedItem> diff(BossSpec spec, Snapshot before, Snapshot after)
	{
		List<LoggedItem> out = new ArrayList<>();
		Map<String, Snapshot.Entry> seen = new LinkedHashMap<>(after.rows);
		for (Map.Entry<String, Snapshot.Entry> row : before.rows.entrySet())
		{
			Snapshot.Entry was = row.getValue();
			Snapshot.Entry now = seen.remove(row.getKey());
			int delta = (now == null ? 0 : now.qty) - was.qty;
			if (delta != 0)
			{
				out.add(logged(spec, now != null ? now : was, delta));
			}
		}
		for (Snapshot.Entry gained : seen.values())
		{
			if (gained.qty != 0)
			{
				out.add(logged(spec, gained, gained.qty));
			}
		}
		return out;
	}

	private LoggedItem logged(BossSpec spec, Snapshot.Entry e, int qty)
	{
		LoggedItem priced = pricer.price(spec, e.representativeId, qty, e.noted);
		if (e.dosesPerItem > 1 && priced.priceEach != null)
		{
			// qty is in doses, so the price must be per dose.
			int perDose = priced.priceEach / e.dosesPerItem;
			return new LoggedItem(priced.itemId, qty, perDose, priced.priceSource,
				priced.noted);
		}
		return priced;
	}
}

package io.github.giwasawa.bosslab.core;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Appends run records to disk, one JSON object per line.
 *
 * <p>Layout, under the plugin's own data directory:
 * <pre>
 *   &lt;RuneLite dir&gt;/plugin-data/boss-lab/&lt;boss-id&gt;/runs-YYYY-MM.jsonl
 *   &lt;RuneLite dir&gt;/plugin-data/boss-lab/&lt;boss-id&gt;/runs-YYYY-MM.jsonl.gz   (previous months)
 * </pre>
 *
 * <p>All access goes through RuneLite's {@link Filepath}, which cannot reach outside
 * the directory the client hands the plugin. File names are generic and never contain
 * the character name. One file per month; when the month turns over, the previous one
 * is gzipped.
 *
 * <p>Every method here is meant to run on RuneLite's injected background executor,
 * never on the client thread, so the game never stutters on a write.
 */
@Slf4j
public class JsonlWriter
{
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("yyyy-MM");

	private final Filepath bossDir;
	private final Gson gson;

	public JsonlWriter(Filepath baseDir, String bossId, Gson gson)
	{
		this.bossDir = baseDir.joinSegment(bossId);
		// Records go out with snake_case field names, which is what
		// data/schema/run-log.schema.json defines and what the Python engine reads.
		// Left to itself Gson would use the Java field names, and nothing downstream
		// could read a single line. Doing it here means no caller can get it wrong.
		// An explicit @SerializedName still wins, so the short item-stack keys stand.
		this.gson = gson.newBuilder()
			.setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
			.create();
	}

	public Filepath directory()
	{
		return bossDir;
	}

	public Filepath currentFile()
	{
		return bossDir.joinSegment("runs-" + MONTH.format(ZonedDateTime.now(ZoneOffset.UTC)) + ".jsonl");
	}

	/**
	 * Append one record. Called on the background executor.
	 *
	 * @return the file written, or null if the write failed
	 */
	public Filepath append(Object record)
	{
		Filepath target = currentFile();
		String line = gson.toJson(record) + "\n";
		try
		{
			bossDir.createDirectories();
			try (Writer w = target.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.APPEND))
			{
				w.write(line);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("boss lab could not write {}", target, e);
			return null;
		}
		return target;
	}

	/** The run files in this boss's folder. Empty when the folder is not there yet. */
	private List<Filepath> runFiles()
	{
		if (!bossDir.isDirectory())
		{
			return Collections.emptyList();
		}
		try (Stream<Filepath> files = bossDir.walk(1))
		{
			return files
				.filter(f -> f.isFile() && f.getFileName().startsWith("runs-"))
				.collect(Collectors.toList());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("boss lab could not list {}", bossDir, e);
			return Collections.emptyList();
		}
	}

	/**
	 * Gzip any month that is not the current one and is not compressed yet.
	 *
	 * <p>Called on the background executor, at startup and after each write, so a long
	 * session that crosses a month boundary still rotates.
	 */
	public void rotate()
	{
		String current = "runs-" + MONTH.format(ZonedDateTime.now(ZoneOffset.UTC)) + ".jsonl";
		for (Filepath f : runFiles())
		{
			String name = f.getFileName();
			if (!name.endsWith(".jsonl") || name.equals(current))
			{
				continue;
			}
			Filepath gz = bossDir.joinSegment(name + ".gz");
			if (gz.exists())
			{
				continue;
			}
			if (gzip(f, gz))
			{
				try
				{
					f.delete();
				}
				catch (IOException e)
				{
					log.warn("boss lab compressed {} but could not remove the original", f);
				}
			}
		}
	}

	private boolean gzip(Filepath from, Filepath to)
	{
		Filepath tmp = bossDir.joinSegment(to.getFileName() + ".part");
		try
		{
			try (InputStream in = from.openInputStream();
				 OutputStream out = new GZIPOutputStream(tmp.openOutputStream()))
			{
				byte[] buf = new byte[8192];
				int n;
				while ((n = in.read(buf)) > 0)
				{
					out.write(buf, 0, n);
				}
			}
			// Only publish the compressed file once it is complete, so an interrupted
			// rotation can never leave a truncated .gz in place of real data.
			tmp.moveTo(to);
			return true;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("boss lab could not compress {}", from, e);
			discard(tmp);
			return false;
		}
	}

	private static void discard(Filepath tmp)
	{
		try
		{
			tmp.deleteIfExists();
		}
		catch (IOException | RuntimeException ignored)
		{
			// A leftover .part file is harmless and is overwritten next time.
		}
	}

	/**
	 * Drop raw per-boundary detail from months older than the limit, keeping the run
	 * summary. Config option "Keep raw events for N months"; 0 keeps everything forever.
	 *
	 * <p>Money totals are computed and written into each record BEFORE its diffs are
	 * dropped, because once they are gone the figures cannot be recomputed. So a pruned
	 * month still reports the right gp, just without the per-item detail behind it.
	 *
	 * <p>Rewrites are atomic: a temporary file is written and then moved over the
	 * original, so an interrupted prune cannot leave a half-written log in place of
	 * real data.
	 *
	 * <p>Called on the background executor.
	 */
	public void prune(int keepMonths)
	{
		if (keepMonths <= 0)
		{
			return;
		}
		YearMonth cutoff = YearMonth.now(ZoneOffset.UTC).minusMonths(keepMonths);
		for (Filepath f : runFiles())
		{
			String name = f.getFileName();
			if (!name.endsWith(".jsonl") && !name.endsWith(".jsonl.gz"))
			{
				continue;
			}
			YearMonth month = monthOf(name);
			if (month == null || !month.isBefore(cutoff))
			{
				continue;
			}
			try
			{
				pruneFile(f);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("boss lab could not prune {}, leaving it alone", name, e);
			}
		}
	}

	private void pruneFile(Filepath f) throws IOException
	{
		boolean gz = f.getFileName().endsWith(".gz");
		List<String> out = new ArrayList<>();
		int changed = 0;

		try (BufferedReader r = new BufferedReader(new InputStreamReader(
			gz ? new GZIPInputStream(f.openInputStream()) : f.openInputStream(),
			StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.trim().isEmpty())
				{
					continue;
				}
				JsonObject run;
				try
				{
					// RuneLite bundles Gson 2.8.5, where JsonParser has no static
					// parseString, so go through the injected Gson instead.
					run = gson.fromJson(line, JsonObject.class);
				}
				catch (RuntimeException e)
				{
					// Keep a line we cannot parse rather than discard a player's data.
					out.add(line);
					continue;
				}
				if (run == null || (run.has("pruned") && run.get("pruned").getAsBoolean()))
				{
					out.add(line);
					continue;
				}
				pruneRun(run);
				out.add(gson.toJson(run));
				changed++;
			}
		}

		if (changed == 0)
		{
			return;
		}

		Filepath tmp = bossDir.joinSegment(f.getFileName() + ".part");
		try
		{
			try (Writer w = new BufferedWriter(new OutputStreamWriter(
				gz ? new GZIPOutputStream(tmp.openOutputStream()) : tmp.openOutputStream(),
				StandardCharsets.UTF_8)))
			{
				for (String line : out)
				{
					w.write(line);
					w.write("\n");
				}
			}
			tmp.moveTo(f, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException | RuntimeException e)
		{
			discard(tmp);
			throw e;
		}
		log.debug("boss lab pruned {} run(s) of raw detail from {}", changed, f.getFileName());
	}

	/** Bake the totals in, then drop the raw detail they were computed from. */
	private void pruneRun(JsonObject run)
	{
		String outcome = run.has("outcome") && !run.get("outcome").isJsonNull()
			? run.get("outcome").getAsString() : "unknown";
		boolean died = "death".equals(outcome);
		// Only a claim banks the loot. A run that ended any other way is not known to
		// have kept anything, so it counts nothing rather than assuming the best.
		boolean claimed = "claim".equals(outcome);
		long loot = 0;
		long supplies = 0;

		JsonArray boundaries = run.getAsJsonArray("boundaries");
		if (boundaries != null)
		{
			for (JsonElement el : boundaries)
			{
				JsonObject b = el.getAsJsonObject();
				loot += sumStacks(b.getAsJsonArray("loot"), false);
				for (String field : new String[]{"inventory_diff", "equipment_diff", "rune_pouch_diff"})
				{
					supplies += sumStacks(b.getAsJsonArray(field), true);
				}
				// The detail goes; the summary of the boundary stays.
				b.remove("loot");
				b.remove("inventory_diff");
				b.remove("equipment_diff");
				b.remove("rune_pouch_diff");
			}
		}

		long kept = claimed ? loot : 0;
		long lost = 0;
		if (died)
		{
			lost = run.has("chest_value_last") && !run.get("chest_value_last").isJsonNull()
				? run.get("chest_value_last").getAsLong() : loot;
		}
		long fee = died && run.has("death_fee") && !run.get("death_fee").isJsonNull()
			? run.get("death_fee").getAsLong() : 0;

		JsonObject totals = new JsonObject();
		totals.addProperty("loot", kept);
		totals.addProperty("loot_lost", lost);
		totals.addProperty("supplies", supplies);
		totals.addProperty("net", kept - supplies - fee);
		run.add("totals", totals);
		run.addProperty("pruned", true);

		run.remove("inventory_start");
		run.remove("equipment_start");
		run.remove("rune_pouch_start");
		run.remove("unknown_events");
	}

	/**
	 * Add up a list of logged stacks.
	 *
	 * @param consumedOnly true to count only the negative quantities, as a positive
	 *                     number: that is what a supply cost is made of
	 */
	private long sumStacks(JsonArray stacks, boolean consumedOnly)
	{
		if (stacks == null)
		{
			return 0;
		}
		long total = 0;
		for (JsonElement el : stacks)
		{
			JsonObject s = el.getAsJsonObject();
			if (!s.has("p") || s.get("p").isJsonNull())
			{
				// An unpriced item contributes nothing rather than a guess.
				continue;
			}
			long qty = s.get("q").getAsLong();
			long price = s.get("p").getAsLong();
			if (consumedOnly)
			{
				if (qty < 0)
				{
					total += -qty * price;
				}
			}
			else
			{
				total += qty * price;
			}
		}
		return total;
	}

	private YearMonth monthOf(String name)
	{
		try
		{
			int i = name.indexOf("runs-") + 5;
			return YearMonth.parse(name.substring(i, i + 7));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static final Pattern STARTED_AT =
		Pattern.compile("\"started_at\":\"(\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\dZ)\"");

	/**
	 * Runs started today, for the side panel.
	 *
	 * <p>"Today" is the player's own day, not the UTC one: records carry UTC times, so
	 * the local midnights are converted and the stamps compared as text, which sorts
	 * the same as time in this format. The previous month's file is read too, since a
	 * local day can straddle the UTC month. Called on the background executor.
	 */
	public int countToday()
	{
		return countBetween(
			LocalDate.now().atStartOfDay(ZoneId.systemDefault()).toInstant(),
			LocalDate.now().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant());
	}

	int countBetween(Instant from, Instant to)
	{
		DateTimeFormatter stamp =
			DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss'Z'").withZone(ZoneOffset.UTC);
		String lo = stamp.format(from);
		String hi = stamp.format(to);
		int count = 0;
		for (String month : new String[]{MONTH.format(from.atZone(ZoneOffset.UTC)),
			MONTH.format(to.atZone(ZoneOffset.UTC))})
		{
			Filepath f = bossDir.joinSegment("runs-" + month + ".jsonl");
			if (!f.exists())
			{
				continue;
			}
			try (BufferedReader r = f.openBufferedReader())
			{
				count += (int) r.lines().filter(line -> {
					Matcher m = STARTED_AT.matcher(line);
					return m.find() && m.group(1).compareTo(lo) >= 0 && m.group(1).compareTo(hi) < 0;
				}).count();
			}
			catch (IOException | RuntimeException e)
			{
				// A count for a status panel is not worth a stack trace.
			}
			if (lo.substring(0, 7).equals(hi.substring(0, 7)))
			{
				break;
			}
		}
		return count;
	}
}

package io.github.giwasawa.bosslab.core;

import io.github.giwasawa.bosslab.core.model.LoggedItem;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Prices an item at the moment it is recorded.
 *
 * <p>Prices come from {@link ItemManager#getItemPrice}, a local lookup in the price
 * table RuneLite downloads and refreshes by itself, whether or not this plugin is
 * installed. So this plugin adds zero network requests, to the wiki or anyone else, no
 * matter how many players use it. This must never be replaced with direct calls to the
 * wiki prices API.
 *
 * <p>Order of checks, from section 4.1 of the brief:
 * <ol>
 *   <li>a {@code crafted_value} rule in the spec, with each part priced now</li>
 *   <li>otherwise, is the item untradeable per {@link ItemComposition#isTradeable()}
 *       (not "its price is 0")? Then 0 gp</li>
 *   <li>otherwise the current price; and if a tradeable item has no price, record null
 *       and flag it rather than guess</li>
 * </ol>
 */
@Singleton
public class Pricer
{
	private final ItemManager itemManager;

	@Inject
	public Pricer(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Build a logged stack, deciding the price now so it is fixed in the log for good.
	 *
	 * @param canonicalId the unnoted id, which is what carries a price
	 * @param noted       whether the stack was held in noted form
	 */
	public LoggedItem price(BossSpec spec, int canonicalId, int qty, boolean noted)
	{
		BossSpec.CraftedValue rule = spec.crafted(canonicalId);
		if (rule != null)
		{
			Integer v = craftedValue(rule);
			if (v != null)
			{
				return new LoggedItem(canonicalId, qty, v,
					LoggedItem.PriceSource.CRAFTED, noted ? Boolean.TRUE : null);
			}
			// Fall through rather than report 0: a crafted item valued at 0 would be wrong.
		}

		if (canonicalId == ItemID.COINS || canonicalId == ItemID.PLATINUM)
		{
			// Currency cannot be traded on the Grand Exchange, so the tradeability test
			// below would call it worthless. ItemManager prices it at face value.
			return new LoggedItem(canonicalId, qty, (int) safePrice(canonicalId),
				LoggedItem.PriceSource.ITEM_MANAGER, noted ? Boolean.TRUE : null);
		}

		if (isUntradeable(spec, canonicalId))
		{
			return new LoggedItem(canonicalId, qty, 0,
				LoggedItem.PriceSource.UNTRADEABLE_ZERO, noted ? Boolean.TRUE : null);
		}

		long price = safePrice(canonicalId);
		if (price <= 0)
		{
			// Tradeable but unpriced. Null is not zero, and we do not guess.
			return new LoggedItem(canonicalId, qty, null,
				LoggedItem.PriceSource.MISSING, noted ? Boolean.TRUE : null);
		}
		return new LoggedItem(canonicalId, qty, (int) Math.min(price, Integer.MAX_VALUE),
			LoggedItem.PriceSource.ITEM_MANAGER, noted ? Boolean.TRUE : null);
	}

	/**
	 * Worth of an item whose price is not its own.
	 *
	 * <p>For Doom this is the Mokhaiotl cloth: the confliction gauntlets it becomes,
	 * less the tormented bracelet and the 10,000 demon tears consumed, less GE tax.
	 * Returns null if any part has no price, so the caller can decide rather than guess.
	 */
	Integer craftedValue(BossSpec.CraftedValue rule)
	{
		long output = safePrice(rule.outputItemId);
		if (output <= 0)
		{
			return null;
		}
		long total = output;
		for (BossSpec.CraftedValue.Part p : rule.subtract)
		{
			long each = safePrice(p.itemId);
			if (each <= 0)
			{
				return null;
			}
			total -= each * (long) p.qty;
		}
		if (rule.geTaxRate > 0)
		{
			long tax = (long) (output * rule.geTaxRate);
			if (rule.geTaxCap > 0)
			{
				tax = Math.min(tax, rule.geTaxCap);
			}
			total -= tax;
		}
		if (total <= 0)
		{
			return null;
		}
		return (int) Math.min(total, Integer.MAX_VALUE);
	}

	/**
	 * The brief is explicit: test tradeability, not "price is 0". A tradeable item can
	 * legitimately have no price, and that is a gap to flag rather than a zero.
	 */
	private boolean isUntradeable(BossSpec spec, int itemId)
	{
		ItemComposition comp = composition(itemId);
		if (comp != null)
		{
			if (!comp.isTradeable())
			{
				return true;
			}
			// Some items are matched by name because their id varies per instance,
			// such as an elite clue scroll.
			return spec.expectedUntradeableName(comp.getName());
		}
		// No composition available, so fall back to the spec's documented list.
		return spec.expectedUntradeable(itemId);
	}

	private long safePrice(int itemId)
	{
		try
		{
			return itemManager.getItemPrice(itemId);
		}
		catch (RuntimeException e)
		{
			return 0;
		}
	}

	ItemComposition composition(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

package io.github.giwasawa.bosslab.core;

/**
 * The only surface a boss module may touch.
 *
 * <p>Modules interpret events; they never build records, price items, or write files.
 * Everything here hands work to the core, which queues file writes onto RuneLite's
 * injected background executor. A module therefore cannot stall the client thread even
 * by accident, and cannot reach anything that would breach the data-only rule.
 */
public interface RunContext
{
	/** Begin a run. Takes the full starting snapshot. Ignored if one is already open. */
	void startRun();

	/**
	 * A boundary has started: the player is now fighting it.
	 *
	 * <p>Closes the idle gap after the previous boundary. Ignored if one is already
	 * open, so a repeated signal is harmless. Starts a run if none is open.
	 */
	void beginBoundary(int index);

	/**
	 * Take back a {@link #beginBoundary} that turned out to be premature.
	 *
	 * <p>Whatever was counted against it is folded into the previous boundary, and the
	 * idle gap is treated as never having ended.
	 */
	void cancelBoundary();

	/**
	 * Close a boundary.
	 *
	 * <p>Safe to call twice for the same cleared boundary: a boss can announce a clear
	 * through more than one signal, and the second is ignored.
	 *
	 * @param index  boundary number, uncapped: a deep delve keeps its real number
	 * @param label  how the scoreboard names it, for example "8+"
	 * @param cleared true if survived, false if this is where the player died
	 */
	void closeBoundary(int index, String label, boolean cleared);

	/** Record the interface's own total, kept alongside our computed one for comparison. */
	void recordChestValue(int valueGp);

	/** Record a unique the moment it is rolled, even if the run later ends in a death. */
	void recordUnique(String uniqueKey);

	/** Record a parsed duration and personal best line. */
	void recordPb(Object delve, double durationS, Double pbS, Boolean isNewPb);

	/** Record the "Deep delves completed: N" figure. */
	void recordDeepDelves(int count);

	/** Record a reclaim fee, when the game showed one. */
	void recordDeathFee(int gp);

	/**
	 * End the run and queue it for writing. Outcome is claim, death, logout or unknown.
	 *
	 * <p>A run in which a boundary closed as a death always ends as a death, whatever
	 * is passed here, so a logout straight after dying cannot relabel it.
	 */
	void endRun(String outcome);

	/** True when a run is open, so a module can avoid pointless work. */
	boolean runOpen();

	/** True while a boundary is being fought, false between boundaries. */
	boolean boundaryOpen();

	/** The boundary being fought, else the last one closed, else 0. */
	int currentBoundary();

	/** The last boundary that closed in this run, or 0 if none has. */
	int lastClosedBoundary();

	/** Capture mode only: note an id the spec does not map yet. */
	void capture(String kind, Integer id, String detail);

	/** Capture mode only: note the map region the player is in, inside the boss area. */
	void captureRegion();

	/** Whether capture mode is on, so a module can skip gathering ids when it is off. */
	boolean capturing();

	/** The loaded spec for this boss, as data. */
	BossSpec spec();

	/** Current game tick, for timing. */
	int tick();

	/** Whether the player is in an instanced area right now. */
	boolean inInstance();

	/**
	 * Read a widget's text, or null when it is absent or empty.
	 *
	 * <p>Modules go through the context rather than holding the client, so the data-only
	 * rules stay enforceable in one place.
	 */
	String widgetText(int componentId);

	/** Read the text of one static child of a widget, or null. */
	String widgetChildText(int componentId, int child);

	/**
	 * Record the loot a run has accumulated so far, from an item container.
	 *
	 * <p>The container is a running pile, so only what was added since the last reading
	 * is recorded, against the last boundary that closed and priced at this moment.
	 * Reading the same pile twice records nothing the second time.
	 *
	 * @return how many stacks the pile holds, or -1 when the container is not there
	 */
	int recordLootPile(int inventoryId);

	/** As {@link #recordLootPile}, reading the pile from a widget's item children. */
	int recordLootFromWidget(int componentId);
}

package io.github.giwasawa.bosslab.core;

import io.github.giwasawa.bosslab.core.model.BoundaryRecord;
import io.github.giwasawa.bosslab.core.model.RunRecord;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Filepath;

/**
 * Owns the run lifecycle and implements the only API a boss module may call.
 *
 * <p>Division of labour: a module says "this boundary just began" or "just closed"; this
 * class decides what that means for the record, takes the snapshots, prices the items
 * and hands the finished record to the writer on the background executor. A module never
 * writes a file and never touches a price.
 *
 * <p>A run is a sequence of boundaries. At any moment either one boundary is open, being
 * fought, or none is and the player is between boundaries. Damage and prayer go to the
 * open boundary; loot goes to the last one that closed, because that is the one the
 * loot was earned in.
 *
 * <p>The run id is a random UUID fragment. It is derived from nothing about the account,
 * and no character name, account hash, or other player ever enters a record.
 */
@Slf4j
public class RunRecorder implements RunContext
{
	private static final DateTimeFormatter UTC =
		DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss'Z'").withZone(ZoneOffset.UTC);

	/** A cap, so a mis-set capture mode cannot grow a log without bound. */
	private static final int MAX_CAPTURED = 400;

	private final Client client;
	private final InventoryTracker tracker;
	private final BossSpec spec;
	private final JsonlWriter writer;
	private final ScheduledExecutorService executor;
	private final String pluginVersion;
	private final Consumer<Filepath> onWritten;

	private RunRecord run;
	/** The boundary being fought, or null between boundaries. */
	private BoundaryRecord open;
	/** True once a boundary has closed as a death. The run can then only end as one. */
	private boolean died;

	private InventoryTracker.Snapshot invAtBoundary;
	private InventoryTracker.Snapshot equipAtBoundary;
	private InventoryTracker.Snapshot pouchAtBoundary;

	private long boundaryStartedMs;
	private int boundaryStartTick;
	/** When the last boundary closed. Idle time runs from here to the next begin. */
	private long lastClosedMs;

	/** The loot pile as last read, item id to quantity, so only additions are recorded. */
	private Map<Integer, Integer> pile = new HashMap<>();

	/** Capture mode: ids already noted in this run, so each is written once. */
	private final Set<String> captured = new HashSet<>();

	private boolean captureMode;
	private int keepMonths;

	public RunRecorder(Client client, InventoryTracker tracker, BossSpec spec,
					   JsonlWriter writer, ScheduledExecutorService executor,
					   String pluginVersion, Consumer<Filepath> onWritten)
	{
		this.client = client;
		this.tracker = tracker;
		this.spec = spec;
		this.writer = writer;
		this.executor = executor;
		this.pluginVersion = pluginVersion;
		this.onWritten = onWritten;
	}

	public void setCaptureMode(boolean on)
	{
		this.captureMode = on;
	}

	public void setKeepMonths(int months)
	{
		this.keepMonths = months;
	}

	// ---- RunContext: lifecycle ---------------------------------------
	@Override
	public void startRun()
	{
		if (run != null)
		{
			return;
		}
		reset();
		run = new RunRecord();
		run.pluginVersion = pluginVersion;
		run.boss = spec.id;
		run.specVersion = spec.version;
		run.runId = UUID.randomUUID().toString().replace("-", "").substring(0, 12);
		run.startedAt = now();
		run.startTick = client.getTickCount();

		invAtBoundary = tracker.inventory();
		equipAtBoundary = tracker.equipment();
		pouchAtBoundary = tracker.runePouch();
		run.inventoryStart.addAll(tracker.toLogged(spec, invAtBoundary));
		run.equipmentStart.addAll(tracker.toLogged(spec, equipAtBoundary));
		run.runePouchStart.addAll(tracker.toLogged(spec, pouchAtBoundary));

		boundaryStartedMs = System.currentTimeMillis();
		lastClosedMs = boundaryStartedMs;
		boundaryStartTick = run.startTick;
		log.debug("boss lab: run {} started", run.runId);
	}

	@Override
	public void beginBoundary(int index)
	{
		if (run == null)
		{
			startRun();
		}
		if (died || open != null)
		{
			return;
		}
		long nowMs = System.currentTimeMillis();
		BoundaryRecord prev = lastClosed();
		if (prev != null)
		{
			prev.idleS = round((nowMs - lastClosedMs) / 1000.0);
		}
		open = new BoundaryRecord(index);
		open.label = spec.labelFor(index);
		boundaryStartedMs = nowMs;
		boundaryStartTick = client.getTickCount();
	}

	@Override
	public void cancelBoundary()
	{
		if (open == null)
		{
			return;
		}
		BoundaryRecord prev = lastClosed();
		if (prev != null)
		{
			prev.damageTaken += open.damageTaken;
			prev.prayerUsed += open.prayerUsed;
			for (String u : open.uniques)
			{
				if (!prev.uniques.contains(u))
				{
					prev.uniques.add(u);
				}
			}
			// The gap never ended, so whatever was measured for it is void.
			prev.idleS = null;
			boundaryStartedMs = lastClosedMs;
			if (prev.endTick != null)
			{
				boundaryStartTick = prev.endTick;
			}
		}
		open = null;
	}

	@Override
	public void closeBoundary(int index, String label, boolean cleared)
	{
		if (died)
		{
			return;
		}
		BoundaryRecord prev = lastClosed();
		if (run != null && prev != null && cleared && prev.index == index)
		{
			// The same clear, announced a second way.
			return;
		}
		if (run != null && prev != null && !cleared && index <= prev.index)
		{
			// A death is always in the boundary after the last one cleared.
			index = prev.index + 1;
		}
		else if (run != null && prev != null && index < prev.index)
		{
			// Boundary numbers only go up within a run. One going down means a new run
			// began without the old one being seen to end, so end it here.
			endRun("unknown");
		}
		if (run == null)
		{
			// A boundary without a run means we joined part-way. Open one so the rest of
			// the run is still recorded, rather than dropping it on the floor.
			startRun();
		}

		BoundaryRecord b = open != null ? open : new BoundaryRecord(index);
		b.index = index;
		b.label = label != null ? label : spec.labelFor(index);
		b.result = cleared ? "cleared" : "died";
		b.startTick = boundaryStartTick;
		b.endTick = client.getTickCount();
		b.startedAt = iso(boundaryStartedMs);
		b.endedAt = now();
		long nowMs = System.currentTimeMillis();
		if (b.durationS == null)
		{
			b.durationS = round((nowMs - boundaryStartedMs) / 1000.0);
		}

		InventoryTracker.Snapshot inv = tracker.inventory();
		InventoryTracker.Snapshot equip = tracker.equipment();
		InventoryTracker.Snapshot pouch = tracker.runePouch();
		b.inventoryDiff.addAll(tracker.diff(spec, invAtBoundary, inv));
		b.equipmentDiff.addAll(tracker.diff(spec, equipAtBoundary, equip));
		b.runePouchDiff.addAll(tracker.diff(spec, pouchAtBoundary, pouch));
		invAtBoundary = inv;
		equipAtBoundary = equip;
		pouchAtBoundary = pouch;

		run.boundaries.add(b);
		run.depthReached = Math.max(run.depthReached, index);
		open = null;
		died = !cleared;

		lastClosedMs = nowMs;
		boundaryStartedMs = nowMs;
		boundaryStartTick = b.endTick;
	}

	@Override
	public void endRun(String outcome)
	{
		if (run == null)
		{
			return;
		}
		RunRecord finished = run;
		finished.outcome = died ? "death" : outcome;
		finished.endedAt = now();
		finished.endTick = client.getTickCount();
		// A boundary still being fought when the run ends was neither cleared nor died
		// in, so it is not a boundary of the record.
		reset();

		if (finished.boundaries.isEmpty() && finished.unknownEvents.isEmpty())
		{
			// Nothing happened, so there is nothing worth a line in the log. A record
			// with captured events but no boundaries IS worth keeping: that is what a
			// capture-mode session looks like when no signal matched, and it carries
			// the raw text needed to fix them.
			return;
		}
		// The last boundary of a run has no idle time, by definition.
		if (!finished.boundaries.isEmpty())
		{
			finished.boundaries.get(finished.boundaries.size() - 1).idleS = null;
		}
		if (!"death".equals(finished.outcome))
		{
			finished.deathFee = null;
		}
		if ("claim".equals(finished.outcome))
		{
			// Only meaningful when the loot was not banked.
			finished.chestValueLast = null;
		}

		final int keep = keepMonths;
		executor.execute(() -> {
			Filepath written = writer.append(finished);
			writer.rotate();
			writer.prune(keep);
			if (written != null && onWritten != null)
			{
				onWritten.accept(written);
			}
		});
		log.debug("boss lab: run queued, outcome {}, depth {}", finished.outcome, finished.depthReached);
	}

	@Override
	public boolean runOpen()
	{
		return run != null;
	}

	@Override
	public boolean boundaryOpen()
	{
		return open != null;
	}

	@Override
	public int currentBoundary()
	{
		return open != null ? open.index : lastClosedBoundary();
	}

	@Override
	public int lastClosedBoundary()
	{
		BoundaryRecord prev = lastClosed();
		return prev == null ? 0 : prev.index;
	}

	// ---- RunContext: what a boundary earned --------------------------
	@Override
	public void recordChestValue(int valueGp)
	{
		if (run == null)
		{
			return;
		}
		BoundaryRecord target = lastClosed();
		if (target != null)
		{
			target.chestValueGp = valueGp;
		}
		// Carried forward so a death, which shows no chest at all, still knows what
		// was forfeited.
		run.chestValueLast = valueGp;
	}

	@Override
	public void recordUnique(String uniqueKey)
	{
		BoundaryRecord target = openOrLast();
		if (target != null && !target.uniques.contains(uniqueKey))
		{
			target.uniques.add(uniqueKey);
		}
	}

	@Override
	public void recordPb(Object delve, double durationS, Double pbS, Boolean isNewPb)
	{
		if (run == null)
		{
			return;
		}
		RunRecord.PbLine line = new RunRecord.PbLine();
		line.delve = delve;
		line.durationS = durationS;
		line.pbS = pbS;
		line.isNewPb = isNewPb;
		run.pbLines.add(line);

		// The chat line is the game's own timing, so prefer it over our wall clock.
		if (delve instanceof Integer)
		{
			for (BoundaryRecord b : run.boundaries)
			{
				if (b.index == (Integer) delve)
				{
					b.durationS = durationS;
				}
			}
			if (open != null && open.index == (Integer) delve)
			{
				open.durationS = durationS;
			}
		}
	}

	@Override
	public void recordDeepDelves(int count)
	{
		if (run != null)
		{
			run.deepDelvesCompleted = count;
		}
	}

	@Override
	public void recordDeathFee(int gp)
	{
		if (run != null)
		{
			run.deathFee = gp;
		}
	}

	@Override
	public int recordLootPile(int inventoryId)
	{
		ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return -1;
		}
		Map<Integer, Integer> now = new LinkedHashMap<>();
		Item[] items = container.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item != null && item.getId() > 0 && item.getQuantity() > 0)
				{
					now.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		return applyPile(now);
	}

	@Override
	public int recordLootFromWidget(int componentId)
	{
		Widget w = client.getWidget(componentId);
		if (w == null)
		{
			return 0;
		}
		Map<Integer, Integer> now = new LinkedHashMap<>();
		collect(now, w.getDynamicChildren());
		if (now.isEmpty())
		{
			collect(now, w.getChildren());
		}
		return applyPile(now);
	}

	private static void collect(Map<Integer, Integer> into, Widget[] children)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			if (child != null && child.getItemId() > 0 && child.getItemQuantity() > 0)
			{
				into.merge(child.getItemId(), child.getItemQuantity(), Integer::sum);
			}
		}
	}

	/**
	 * Record what the pile gained since it was last read.
	 *
	 * <p>The pile accumulates across a run, so a boundary's own loot is the difference
	 * between two readings. Each addition is priced now, which is the moment the chest
	 * showed it. Should a pile ever shrink, it is not the same pile continuing, and the
	 * whole of it is taken as new rather than recording a negative.
	 */
	private int applyPile(Map<Integer, Integer> now)
	{
		BoundaryRecord target = lastClosed();
		if (run == null || target == null || now.isEmpty())
		{
			return now.size();
		}
		Map<Integer, Integer> base = pile;
		for (Map.Entry<Integer, Integer> was : pile.entrySet())
		{
			if (now.getOrDefault(was.getKey(), 0) < was.getValue())
			{
				base = new HashMap<>();
				break;
			}
		}
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			int gained = e.getValue() - base.getOrDefault(e.getKey(), 0);
			if (gained <= 0)
			{
				continue;
			}
			target.loot.add(tracker.lootItem(spec, e.getKey(), gained));
			// A unique is recorded the moment it shows, even if the run then dies.
			String unique = spec.uniqueKeyForItem(e.getKey());
			if (unique != null && !target.uniques.contains(unique))
			{
				target.uniques.add(unique);
			}
		}
		pile = new HashMap<>(now);
		return now.size();
	}

	// ---- RunContext: reading the game --------------------------------
	@Override
	public void capture(String kind, Integer id, String detail)
	{
		if (!captureMode || run == null || run.unknownEvents.size() >= MAX_CAPTURED)
		{
			return;
		}
		// Chat is kept line by line, since the order and repetition are the point.
		// Everything else is an id, and seeing it once is all there is to learn.
		if (!"chat".equals(kind) && !captured.add(kind + ":" + id + ":" + detail))
		{
			return;
		}
		run.unknownEvents.add(new RunRecord.UnknownEvent(kind, client.getTickCount(), id, detail));
	}

	@Override
	public void captureRegion()
	{
		if (!captureMode || run == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		LocalPoint at = local == null ? null : local.getLocalLocation();
		if (at == null)
		{
			return;
		}
		// In an instance the live coordinates are arbitrary; the template they were
		// copied from is the stable part, and it is still only the boss area.
		WorldPoint template = WorldPoint.fromLocalInstance(client, at);
		if (template != null)
		{
			capture("region", template.getRegionID(), inInstance() ? "instance" : null);
		}
	}

	@Override
	public boolean capturing()
	{
		return captureMode;
	}

	@Override
	public BossSpec spec()
	{
		return spec;
	}

	@Override
	public int tick()
	{
		return client.getTickCount();
	}

	@Override
	public boolean inInstance()
	{
		WorldView view = client.getTopLevelWorldView();
		return view != null && view.isInstance();
	}

	@Override
	public String widgetText(int componentId)
	{
		return text(client.getWidget(componentId));
	}

	@Override
	public String widgetChildText(int componentId, int child)
	{
		Widget w = client.getWidget(componentId);
		return w == null ? null : text(w.getChild(child));
	}

	private static String text(Widget w)
	{
		if (w == null || w.isHidden())
		{
			return null;
		}
		String text = w.getText();
		return text == null || text.isEmpty() ? null : text;
	}

	// ---- damage and prayer, fed by the plugin's event handlers --------
	public void addDamageTaken(int amount)
	{
		BoundaryRecord target = openOrLast();
		if (target != null)
		{
			target.damageTaken += amount;
		}
	}

	public void addPrayerUsed(int points)
	{
		BoundaryRecord target = openOrLast();
		if (target != null)
		{
			target.prayerUsed += points;
		}
	}

	// ---- helpers -----------------------------------------------------
	private BoundaryRecord lastClosed()
	{
		if (run == null || run.boundaries.isEmpty())
		{
			return null;
		}
		return run.boundaries.get(run.boundaries.size() - 1);
	}

	private BoundaryRecord openOrLast()
	{
		return open != null ? open : lastClosed();
	}

	private void reset()
	{
		run = null;
		open = null;
		died = false;
		pile = new HashMap<>();
		captured.clear();
	}

	private static String now()
	{
		return UTC.format(Instant.now());
	}

	private static String iso(long ms)
	{
		return UTC.format(Instant.ofEpochMilli(ms));
	}

	private static double round(double v)
	{
		return Math.round(v * 10.0) / 10.0;
	}
}

package io.github.giwasawa.bosslab.core.model;

import java.util.ArrayList;
import java.util.List;

/**
 * One boundary of a run. For Doom that is one delve.
 *
 * <p>Boundaries are not capped: a deep delve past 8 is recorded with its real number,
 * and carries the scoreboard's own "8+" label alongside it.
 */
public class BoundaryRecord
{
	/** Not final: a run joined part-way learns a boundary's real number only when it closes. */
	public int index;
	public String label;
	/** "cleared" or "died". */
	public String result = "cleared";

	public Integer startTick;
	public Integer endTick;
	public String startedAt;
	public String endedAt;
	public Double durationS;

	/**
	 * From this boundary's chest appearing to the next one starting: looting, restoring,
	 * positioning. Null on the last boundary of a run, which has no idle time.
	 */
	public Double idleS;

	public final List<LoggedItem> loot = new ArrayList<>();
	public Integer chestValueGp;

	public final List<LoggedItem> inventoryDiff = new ArrayList<>();
	public final List<LoggedItem> equipmentDiff = new ArrayList<>();
	public final List<LoggedItem> runePouchDiff = new ArrayList<>();

	public Integer damageTaken = 0;
	public Integer prayerUsed = 0;

	/** Unique keys rolled here. Recorded the moment one appears, even if the run then dies. */
	public final List<String> uniques = new ArrayList<>();

	public BoundaryRecord(int index)
	{
		this.index = index;
		this.label = Integer.toString(index);
	}
}

package io.github.giwasawa.bosslab.core.model;

import com.google.gson.annotations.SerializedName;

/**
 * A quantity of one item, together with the price that was in force at the moment it
 * was recorded.
 *
 * <p>Section 4.1 of the brief: values never change after they are logged. The engine
 * never re-prices old events, so a run's worth is fixed in the log itself. A price
 * crash or spike only affects events from that moment on.
 *
 * <p>A negative quantity in a diff means the item was consumed. Potions are counted in
 * doses, so a (4) becoming a (3) is a quantity of -1 against the dose unit.
 */
public class LoggedItem
{
	/** How {@link #priceEach} was decided. Lets the dashboard tell a real zero from a gap. */
	public enum PriceSource
	{
		/** RuneLite's own in-memory price table. */
		ITEM_MANAGER("item_manager"),
		/** A crafted_value rule from the boss spec, such as the Mokhaiotl cloth. */
		CRAFTED("crafted"),
		/** ItemComposition reported the item untradeable, so it is worth 0 gp. */
		UNTRADEABLE_ZERO("untradeable_zero"),
		/** Tradeable, but no price was available. priceEach stays null; never guess. */
		MISSING("missing");

		private final String wire;

		PriceSource(String wire)
		{
			this.wire = wire;
		}

		public String wire()
		{
			return wire;
		}
	}

	// Wire names are deliberately short. A run holds dozens of these and section 2.4
	// sets a storage budget of a few KB per run; repeated key names were a third of
	// the file before they were shortened.
	@SerializedName("id")
	public final int itemId;

	@SerializedName("q")
	public final int qty;

	/** Null only when the source is MISSING. Null is not zero. */
	@SerializedName("p")
	public final Integer priceEach;

	/**
	 * Left out entirely when ItemManager supplied the price, which is the common case.
	 * Gson omits a null field, so the rare cases stay explicit and the common one is
	 * free. Readers treat an absent value as ITEM_MANAGER.
	 */
	@SerializedName("src")
	private final String src;

	@SerializedName("n")
	public final Boolean noted;

	/** Not written: the enum is kept for callers, the wire carries {@link #src}. */
	public final transient PriceSource priceSource;

	public LoggedItem(int itemId, int qty, Integer priceEach, PriceSource priceSource, Boolean noted)
	{
		this.itemId = itemId;
		this.qty = qty;
		this.priceEach = priceEach;
		this.priceSource = priceSource;
		this.src = priceSource == PriceSource.ITEM_MANAGER ? null : priceSource.wire();
		this.noted = noted;
	}

	public LoggedItem withQty(int newQty)
	{
		return new LoggedItem(itemId, newQty, priceEach, priceSource, noted);
	}
}

package io.github.giwasawa.bosslab.core.model;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;

/**
 * One run of one boss: the unit the plugin writes, one JSON object per line.
 *
 * <p>Carries no personal data of any kind. No character name, no account hash or id, no
 * other players, no chat from other players, no location outside the boss area. The run
 * id is random and derived from nothing about the account.
 */
public class RunRecord
{
	public static final String SCHEMA_VERSION = "1.0.0";

	public String schemaVersion = SCHEMA_VERSION;
	public String pluginVersion;
	public String boss;
	public String specVersion;
	public String referenceVersion;

	public String runId;
	public String startedAt;
	public String endedAt;
	public Integer startTick;
	public Integer endTick;

	/** "claim", "death", "logout" or "unknown". */
	public String outcome = "unknown";
	public int depthReached;
	public Integer deathFee;

	/**
	 * The last value the loot chest showed before the run ended.
	 *
	 * <p>A death shows no chest interface at all: the value simply goes to zero, less the
	 * reclaim fee. So on a death this field is what was forfeited, carried forward from
	 * the last chest the player did see.
	 */
	public Integer chestValueLast;

	public final List<BoundaryRecord> boundaries = new ArrayList<>();

	public final List<LoggedItem> inventoryStart = new ArrayList<>();
	public final List<LoggedItem> equipmentStart = new ArrayList<>();
	public final List<LoggedItem> runePouchStart = new ArrayList<>();

	public final List<PbLine> pbLines = new ArrayList<>();
	public Integer deepDelvesCompleted;

	public final List<UnknownEvent> unknownEvents = new ArrayList<>();

	/**
	 * Money totals, written only when a month is pruned.
	 *
	 * <p>Once the per-boundary diffs are dropped the figures cannot be recomputed, so
	 * they are fixed here first. Absent on a full record.
	 */
	public Totals totals;

	/** True when raw per-boundary detail was dropped by the keep-raw-months option. */
	public Boolean pruned;

	public static class Totals
	{
		public long loot;
		@SerializedName("loot_lost")
		public long lootLost;
		public long supplies;
		public long net;
	}

	/** A parsed duration and personal best line, rather than the raw text. */
	public static class PbLine
	{
		public Object delve;
		public double durationS;
		public Double pbS;
		public Boolean isNewPb;
	}

	/**
	 * Capture mode only: an id seen inside the boss area that the spec does not yet map.
	 * The player plays a few runs, then the ids go into spec.yaml. Nothing is hard-coded.
	 */
	public static class UnknownEvent
	{
		public String kind;
		public int tick;
		public Integer id;
		public String detail;

		public UnknownEvent(String kind, int tick, Integer id, String detail)
		{
			this.kind = kind;
			this.tick = tick;
			this.id = id;
			this.detail = detail;
		}
	}
}

