package io.github.giwasawa.bosslab;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.client.util.Filepath;

/**
 * Test-only bridges between a temporary folder and RuneLite's {@link Filepath}.
 *
 * <p>The plugin itself never touches {@code Filepath.Unchecked}: it is handed its
 * directory by the client. A test has no client, so it roots one by hand.
 */
public final class TestFiles
{
	private TestFiles()
	{
	}

	public static Filepath rooted(File dir)
	{
		return Filepath.Unchecked.getRooted(dir.toPath());
	}

	public static File file(Filepath fp)
	{
		return Filepath.Unchecked.getFile(fp);
	}

	/** The non-blank lines of a log file. */
	public static List<String> lines(Filepath fp) throws IOException
	{
		return Files.readAllLines(file(fp).toPath(), StandardCharsets.UTF_8).stream()
			.filter(s -> !s.trim().isEmpty())
			.collect(Collectors.toList());
	}
}

package io.github.giwasawa.bosslab.bosses.doom;

import io.github.giwasawa.bosslab.TestFiles;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import io.github.giwasawa.bosslab.core.BossSpec;
import io.github.giwasawa.bosslab.core.InventoryTracker;
import io.github.giwasawa.bosslab.core.JsonlWriter;
import io.github.giwasawa.bosslab.core.Pricer;
import io.github.giwasawa.bosslab.core.RunRecorder;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Capture mode has to work when the chat patterns are WRONG.
 *
 * <p>That is the whole point of it: the wiki documents no in-game message text, so the
 * delve patterns ship unverified and a capture session is how the real wording is
 * learned. There was a circular dependency here worth guarding against. Captured events
 * need an open run to live in, a run normally opens only once a delve line matches, and
 * a record with no boundaries used to be discarded. So a pattern that failed to match
 * produced an empty log and taught us nothing, in exactly the case we needed it most.
 */
public class CaptureModeTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Client client;
	private RunRecorder recorder;
	private JsonlWriter writer;
	private DoomModule module;
	private Gson gson;
	private int tick;

	@Before
	public void setUp() throws Exception
	{
		gson = new Gson();
		client = Mockito.mock(Client.class);
		Mockito.when(client.getTickCount()).thenAnswer(i -> tick);

		ItemManager itemManager = Mockito.mock(ItemManager.class);
		Pricer pricer = new Pricer(itemManager);
		InventoryTracker tracker = new InventoryTracker(client, pricer);
		BossSpec spec = BossSpec.load(gson, "doom-of-mokhaiotl");

		writer = new JsonlWriter(TestFiles.rooted(folder.getRoot()), "doom-of-mokhaiotl", gson);
		// Run queued work inline, so the test does not race the background executor.
		ScheduledExecutorService executor = Mockito.mock(ScheduledExecutorService.class);
		Mockito.doAnswer(i -> {
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(executor).execute(Mockito.any(Runnable.class));

		recorder = new RunRecorder(client, tracker, spec, writer, executor, "test", f -> {
		});
		module = new DoomModule();
	}

	private ChatMessage game(String message)
	{
		ChatMessage e = new ChatMessage();
		e.setType(ChatMessageType.GAMEMESSAGE);
		e.setMessage(message);
		return e;
	}

	/** What BossLabPlugin does when no module is active and a message arrives. */
	private boolean deliver(ChatMessage event)
	{
		if (!module.probeChat(event))
		{
			return false;
		}
		module.onEnterArea(recorder);
		module.onChatMessage(event, recorder);
		return true;
	}

	private void quietUntilRunCloses()
	{
		tick += 600;        // past DoomModule's quiet threshold
		module.onTick(recorder);
	}

	private List<String> written() throws IOException
	{
		File f = TestFiles.file(writer.currentFile());
		return f.exists() ? Files.readAllLines(f.toPath(), StandardCharsets.UTF_8)
			: Collections.emptyList();
	}

	private JsonObject onlyRecord() throws IOException
	{
		List<String> lines = written();
		assertEquals("expected exactly one record", 1, lines.size());
		return gson.fromJson(lines.get(0), JsonObject.class);
	}

	private String capturedChat(JsonObject run)
	{
		JsonArray events = run.getAsJsonArray("unknown_events");
		assertNotNull("the record should carry captured events", events);
		StringBuilder all = new StringBuilder();
		for (JsonElement el : events)
		{
			JsonObject e = el.getAsJsonObject();
			if ("chat".equals(e.get("kind").getAsString()) && e.has("detail"))
			{
				all.append(e.get("detail").getAsString()).append("\n");
			}
		}
		return all.toString();
	}

	@Test
	public void aWrongPatternStillRecordsTheRealWording() throws Exception
	{
		recorder.setCaptureMode(true);

		// Wording the shipped pattern does not match: the colon has moved and the game
		// says "Floor" rather than "duration:". This is the failure we must survive.
		String real = "Delve level 7 complete! Floor duration 2:23 (personal best)";
		assertTrue("the module should still recognise its own boss", deliver(game(real)));

		quietUntilRunCloses();

		JsonObject run = onlyRecord();
		assertTrue("the raw text must reach the log so the pattern can be fixed",
			capturedChat(run).contains(real));
		assertEquals("no boundary was understood, which is the honest outcome",
			0, run.getAsJsonArray("boundaries").size());
		assertEquals("unknown", run.get("outcome").getAsString());
	}

	@Test
	public void aCorrectPatternRecordsTheBoundaryAndTheWordingBoth() throws Exception
	{
		recorder.setCaptureMode(true);

		String real = "Delve level: 7 duration: 2:23. Personal best: 2:20";
		assertTrue(deliver(game(real)));
		quietUntilRunCloses();

		JsonObject run = onlyRecord();
		JsonArray boundaries = run.getAsJsonArray("boundaries");
		assertEquals(1, boundaries.size());
		JsonObject b = boundaries.get(0).getAsJsonObject();
		assertEquals(7, b.get("index").getAsInt());
		assertEquals("cleared", b.get("result").getAsString());
		// The game's own timing beats our wall clock.
		assertEquals(143.0, b.get("duration_s").getAsDouble(), 0.001);
		assertTrue("a matched line is still worth recording verbatim",
			capturedChat(run).contains(real));
	}

	@Test
	public void withCaptureOffAnUnmatchedLineWritesNothing() throws Exception
	{
		recorder.setCaptureMode(false);

		deliver(game("Delve level 7 complete! Floor duration 2:23"));
		quietUntilRunCloses();

		// Everyday play should not accumulate records for lines we cannot read.
		assertTrue("nothing should be written", written().isEmpty());
	}

	@Test
	public void captureModeDoesNotRecordAnythingOutsideTheBossArea() throws Exception
	{
		recorder.setCaptureMode(true);

		// Ordinary chatter elsewhere in the game must not latch the module on, so no
		// location or activity outside the boss area is ever written.
		assertFalse(deliver(game("You feel a surge of power.")));
		assertFalse(deliver(game("Oh dear, you are dead!")));

		assertTrue(written().isEmpty());
	}

	@Test
	public void theDeepDelveLineAlsoIdentifiesTheArea() throws Exception
	{
		recorder.setCaptureMode(true);
		assertTrue(deliver(game("Deep delves completed: 12")));
		quietUntilRunCloses();
		assertEquals(12, onlyRecord().get("deep_delves_completed").getAsInt());
	}

	@Test
	public void colouredMessagesStillMatch() throws Exception
	{
		recorder.setCaptureMode(true);

		// Game messages arrive carrying the game's own colour markup. Matching the raw
		// text would fail on any line the game decides to colour, so the tags come off
		// before the patterns run.
		String coloured = "<col=ef1020>Delve level: 7 duration: 2:23. "
			+ "Personal best: 2:20</col>";
		assertTrue("the probe must see through the markup too", deliver(game(coloured)));
		quietUntilRunCloses();

		JsonObject run = onlyRecord();
		JsonArray boundaries = run.getAsJsonArray("boundaries");
		assertEquals(1, boundaries.size());
		assertEquals(7, boundaries.get(0).getAsJsonObject().get("index").getAsInt());
		assertEquals(143.0,
			boundaries.get(0).getAsJsonObject().get("duration_s").getAsDouble(), 0.001);
		// The capture keeps the markup, because that is what has to be matched in the end.
		assertTrue("the raw form is what gets recorded",
			capturedChat(run).contains("<col=ef1020>"));
	}

	@Test
	public void capturedEventsAreCapped() throws Exception
	{
		recorder.setCaptureMode(true);
		deliver(game("Delve level: 1 duration: 0:40. Personal best: 0:40"));
		for (int i = 0; i < 600; i++)
		{
			module.onChatMessage(game("noise " + i), recorder);
		}
		quietUntilRunCloses();

		// A mis-set capture mode must not grow a log without bound.
		int events = onlyRecord().getAsJsonArray("unknown_events").size();
		assertTrue("capped, got " + events, events <= 400);
	}
}

package io.github.giwasawa.bosslab.bosses.doom;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import io.github.giwasawa.bosslab.TestFiles;
import io.github.giwasawa.bosslab.core.BossSpec;
import io.github.giwasawa.bosslab.core.InventoryTracker;
import io.github.giwasawa.bosslab.core.JsonlWriter;
import io.github.giwasawa.bosslab.core.Pricer;
import io.github.giwasawa.bosslab.core.RunRecorder;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.WorldView;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Whole runs, signal by signal, as the game would deliver them.
 *
 * <p>Each of these is a way a record used to come out wrong: a claim that was never
 * recognised as one, a first delve whose supplies went unmeasured because the run only
 * opened once it was over, a death booked against the delve before it, damage counted
 * against the wrong delve, a fee that arrived after the record had already been
 * written. The signals are also delivered twice and out of order, because the game
 * announces a clear in more than one way and nothing confirms which comes first.
 */
public class DoomRunFlowTest
{
	private static final int CHEST_GROUP = InterfaceID.DOM_END_LEVEL_UI;
	private static final int BOSS = NpcID.DOM_BOSS;
	private static final int CLAIM_SCRIPT = net.runelite.api.ScriptID.DOM_LOOT_CLAIM;

	private static final int SHARK = 385;
	private static final int COAL = 453;
	private static final int COAL_NOTED = 454;
	private static final int CLOTH = 31109;
	private static final int GAUNTLETS = 31106;
	private static final int BRACELET = 19544;
	private static final int TEARS = 31111;
	private static final int COINS = 995;

	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Client client;
	private RunRecorder recorder;
	private JsonlWriter writer;
	private DoomModule module;
	private Gson gson;
	private int tick;
	private boolean instanced = true;

	private final Map<Integer, Integer> inventory = new LinkedHashMap<>();
	private final Map<Integer, Integer> pile = new LinkedHashMap<>();
	private boolean pileExists = true;
	private String title;
	private String valueText;

	@Before
	public void setUp() throws Exception
	{
		gson = new Gson();
		client = Mockito.mock(Client.class);
		Mockito.when(client.getTickCount()).thenAnswer(i -> tick);

		WorldView view = Mockito.mock(WorldView.class);
		Mockito.when(view.isInstance()).thenAnswer(i -> instanced);
		Mockito.when(client.getTopLevelWorldView()).thenReturn(view);

		Mockito.when(client.getItemContainer(InventoryID.INV)).thenAnswer(i -> container(inventory));
		Mockito.when(client.getItemContainer(InventoryID.DOM_LOOTPILE))
			.thenAnswer(i -> pileExists ? container(pile) : null);

		Widget frame = Mockito.mock(Widget.class);
		Widget titleWidget = Mockito.mock(Widget.class);
		Mockito.when(titleWidget.getText()).thenAnswer(i -> title);
		Mockito.when(frame.getChild(1)).thenReturn(titleWidget);
		Mockito.when(client.getWidget(InterfaceID.DomEndLevelUi.FRAME)).thenReturn(frame);

		Widget value = Mockito.mock(Widget.class);
		Mockito.when(value.getText()).thenAnswer(i -> valueText);
		Mockito.when(client.getWidget(InterfaceID.DomEndLevelUi.LOOT_VALUE)).thenReturn(value);

		ItemManager itemManager = Mockito.mock(ItemManager.class);
		item(itemManager, SHARK, "Shark", true, 800, -1, -1);
		item(itemManager, COAL, "Coal", true, 150, -1, COAL_NOTED);
		item(itemManager, COAL_NOTED, "Coal", true, 0, 799, COAL);
		item(itemManager, CLOTH, "Mokhaiotl cloth", false, 0, -1, -1);
		item(itemManager, GAUNTLETS, "Confliction gauntlets", true, 60_000_000, -1, -1);
		item(itemManager, BRACELET, "Tormented bracelet", true, 15_000_000, -1, -1);
		item(itemManager, TEARS, "Demon tear", true, 300, -1, -1);
		item(itemManager, COINS, "Coins", false, 1, -1, -1);

		InventoryTracker tracker = new InventoryTracker(client, new Pricer(itemManager));
		BossSpec spec = BossSpec.load(gson, "doom-of-mokhaiotl");
		writer = new JsonlWriter(TestFiles.rooted(folder.getRoot()), "doom-of-mokhaiotl", gson);

		ScheduledExecutorService executor = Mockito.mock(ScheduledExecutorService.class);
		Mockito.doAnswer(i -> {
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(executor).execute(Mockito.any(Runnable.class));

		recorder = new RunRecorder(client, tracker, spec, writer, executor, "test", f -> {
		});
		module = new DoomModule();
		inventory.put(SHARK, 10);
	}

	private static void item(ItemManager im, int id, String name, boolean tradeable,
							 int price, int note, int linked)
	{
		ItemComposition comp = Mockito.mock(ItemComposition.class);
		Mockito.when(comp.isTradeable()).thenReturn(tradeable);
		Mockito.when(comp.getNote()).thenReturn(note);
		Mockito.when(comp.getLinkedNoteId()).thenReturn(linked);
		Mockito.when(comp.getName()).thenReturn(name);
		Mockito.when(im.getItemComposition(id)).thenReturn(comp);
		Mockito.when(im.getItemPrice(id)).thenReturn((long) price);
	}

	private static ItemContainer container(Map<Integer, Integer> contents)
	{
		List<Item> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : contents.entrySet())
		{
			items.add(new Item(e.getKey(), e.getValue()));
		}
		ItemContainer c = Mockito.mock(ItemContainer.class);
		Mockito.when(c.getItems()).thenReturn(items.toArray(new Item[0]));
		return c;
	}

	// ---- the game's signals, delivered the way BossLabPlugin delivers them ----
	private void bossAppears()
	{
		if (!module.isInArea(null, null))
		{
			assertTrue(module.probeNpc(BOSS, recorder));
			module.onEnterArea(recorder);
		}
		module.onNpcSpawned(BOSS, recorder);
	}

	private void delveLine(int delve, String duration)
	{
		ChatMessage e = game("Delve level: " + delve + " duration: " + duration
			+ ". Personal best: 0:30");
		if (!module.isInArea(null, null))
		{
			assertTrue(module.probeChat(e));
			module.onEnterArea(recorder);
		}
		module.onChatMessage(e, recorder);
	}

	private static ChatMessage game(String message)
	{
		ChatMessage e = new ChatMessage();
		e.setType(ChatMessageType.GAMEMESSAGE);
		e.setMessage(message);
		return e;
	}

	/** The end-of-delve interface opens and, a tick later, has been built and is read. */
	private void chest(int level, String value)
	{
		title = "Level " + level + " Complete!";
		valueText = value;
		WidgetLoaded e = new WidgetLoaded();
		e.setGroupId(CHEST_GROUP);
		if (!module.isInArea(null, null))
		{
			assertTrue(module.probeWidget(CHEST_GROUP, recorder));
			module.onEnterArea(recorder);
		}
		module.onWidgetLoaded(e, recorder);
		tick();
	}

	private void descend()
	{
		module.onWidgetClosed(CHEST_GROUP, recorder);
	}

	private void claim()
	{
		module.onScript(CLAIM_SCRIPT, recorder);
		module.onWidgetClosed(CHEST_GROUP, recorder);
	}

	private void tick()
	{
		tick++;
		module.onTick(recorder);
	}

	private void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick();
		}
	}

	private List<String> written() throws IOException
	{
		return TestFiles.file(writer.currentFile()).exists()
			? TestFiles.lines(writer.currentFile()) : Collections.emptyList();
	}

	private JsonObject onlyRun() throws IOException
	{
		List<String> lines = written();
		assertEquals("expected exactly one record", 1, lines.size());
		return gson.fromJson(lines.get(0), JsonObject.class);
	}

	private static JsonObject boundary(JsonObject run, int i)
	{
		return run.getAsJsonArray("boundaries").get(i).getAsJsonObject();
	}

	private static int qty(JsonArray stacks, int itemId)
	{
		int total = 0;
		for (JsonElement el : stacks)
		{
			JsonObject s = el.getAsJsonObject();
			if (s.get("id").getAsInt() == itemId)
			{
				total += s.get("q").getAsInt();
			}
		}
		return total;
	}

	// ---- a whole run -------------------------------------------------
	@Test
	public void aClaimedRunIsRecordedAsAClaimDelveByDelve() throws Exception
	{
		bossAppears();
		assertTrue("the run opens when the fight does, not when it is over", recorder.runOpen());

		inventory.put(SHARK, 8);                    // two eaten in delve 1
		delveLine(1, "0:45");
		pile.put(COAL, 40);
		chest(1, "Value: 6,000 GP");
		descend();

		recorder.addDamageTaken(30);                // delve 2
		inventory.put(SHARK, 7);
		pile.put(COAL, 100);                        // the pile accumulates
		pile.put(CLOTH, 1);
		chest(2, "Value: 44,000,000 GP");           // no chat line this time
		claim();

		JsonObject run = onlyRun();
		assertEquals("claim", run.get("outcome").getAsString());
		assertEquals(2, run.get("depth_reached").getAsInt());
		assertEquals(2, run.getAsJsonArray("boundaries").size());
		assertFalse("a claim forfeits nothing", run.has("chest_value_last"));
		assertEquals(10, qty(run.getAsJsonArray("inventory_start"), SHARK));

		JsonObject one = boundary(run, 0);
		assertEquals(1, one.get("index").getAsInt());
		assertEquals("cleared", one.get("result").getAsString());
		assertEquals("the game's own timing", 45.0, one.get("duration_s").getAsDouble(), 0.001);
		assertEquals("delve 1's own supplies", -2, qty(one.getAsJsonArray("inventory_diff"), SHARK));
		assertEquals(40, qty(one.getAsJsonArray("loot"), COAL));
		assertEquals(0, one.get("damage_taken").getAsInt());
		assertTrue("idle runs from the chest to the descent", one.has("idle_s"));
		assertEquals(6_000, one.get("chest_value_gp").getAsInt());

		JsonObject two = boundary(run, 1);
		assertEquals(2, two.get("index").getAsInt());
		assertEquals(-1, qty(two.getAsJsonArray("inventory_diff"), SHARK));
		assertEquals("only what this delve added to the pile", 60, qty(two.getAsJsonArray("loot"), COAL));
		assertEquals(1, qty(two.getAsJsonArray("loot"), CLOTH));
		assertEquals("damage lands on the delve it was taken in", 30, two.get("damage_taken").getAsInt());
		assertEquals("cloth", two.getAsJsonArray("uniques").get(0).getAsString());
		assertFalse("the last delve of a run has no idle time", two.has("idle_s"));
	}

	@Test
	public void theClothIsNeverValuedAtZero() throws Exception
	{
		bossAppears();
		delveLine(2, "1:00");
		pile.put(CLOTH, 1);
		chest(2, "Value: 1 GP");
		claim();

		JsonObject cloth = boundary(onlyRun(), 0).getAsJsonArray("loot").get(0).getAsJsonObject();
		// 60M gauntlets - 15M bracelet - 10,000 x 300 tears - 2% tax on the gauntlets.
		assertEquals(60_000_000 - 15_000_000 - 3_000_000 - 1_200_000, cloth.get("p").getAsInt());
		assertEquals("crafted", cloth.get("src").getAsString());
	}

	@Test
	public void notedLootIsLoggedAgainstTheItemThatHasAPrice() throws Exception
	{
		bossAppears();
		pile.put(COAL_NOTED, 25);
		pile.put(COINS, 5_000);
		chest(1, "Value: 8,750 GP");
		claim();

		JsonArray loot = boundary(onlyRun(), 0).getAsJsonArray("loot");
		JsonObject coal = loot.get(0).getAsJsonObject();
		assertEquals(COAL, coal.get("id").getAsInt());
		assertEquals(150, coal.get("p").getAsInt());
		assertTrue(coal.get("n").getAsBoolean());
		JsonObject coins = loot.get(1).getAsJsonObject();
		assertEquals("coins are worth their face value, not nothing", 1, coins.get("p").getAsInt());
	}

	// ---- death -------------------------------------------------------
	@Test
	public void aDeathIsBookedAgainstTheDelveBeingFought() throws Exception
	{
		bossAppears();
		pile.put(COAL, 40);
		chest(1, "Value: 300,000 GP");
		descend();
		recorder.addDamageTaken(99);
		module.onDeath(recorder);

		assertTrue("held open briefly, in case a fee line follows", written().isEmpty());
		ticks(60);

		JsonObject run = onlyRun();
		assertEquals("death", run.get("outcome").getAsString());
		assertEquals(2, run.get("depth_reached").getAsInt());
		assertEquals(2, run.getAsJsonArray("boundaries").size());
		assertEquals("cleared", boundary(run, 0).get("result").getAsString());
		assertEquals(2, boundary(run, 1).get("index").getAsInt());
		assertEquals("died", boundary(run, 1).get("result").getAsString());
		assertEquals(99, boundary(run, 1).get("damage_taken").getAsInt());
		// A death opens no chest, so what was forfeited is whatever the last one said.
		assertEquals(300_000, run.get("chest_value_last").getAsInt());
	}

	@Test
	public void aDeathInTheFirstDelveIsStillARecord() throws Exception
	{
		bossAppears();
		inventory.put(SHARK, 4);
		module.onDeath(recorder);
		ticks(60);

		JsonObject run = onlyRun();
		assertEquals("death", run.get("outcome").getAsString());
		assertEquals(1, boundary(run, 0).get("index").getAsInt());
		assertEquals(-6, qty(boundary(run, 0).getAsJsonArray("inventory_diff"), SHARK));
	}

	@Test
	public void aFeeLineAfterTheDeathIsAttachedToIt() throws Exception
	{
		// The wording is unconfirmed. All that is assumed is a gp figure next to
		// "reclaim" or "retrieve", in either order.
		for (String line : new String[]{
			"You pay 75,000 coins to reclaim your items.",
			"It costs 75,000 gp to retrieve your items.",
			"Reclaim fee: 75,000 coins"})
		{
			setUp();
			TestFiles.file(writer.currentFile()).delete();
			bossAppears();
			chest(1, "Value: 300,000 GP");
			descend();
			module.onDeath(recorder);
			tick();
			module.onChatMessage(game("Oh dear, you are dead!"), recorder);
			assertTrue("still waiting for the fee", written().isEmpty());
			module.onChatMessage(game(line), recorder);

			JsonObject run = onlyRun();
			assertEquals("death", run.get("outcome").getAsString());
			assertEquals(line, 75_000, run.get("death_fee").getAsInt());
		}
	}

	@Test
	public void loggingOutStraightAfterDyingDoesNotRelabelTheDeath() throws Exception
	{
		bossAppears();
		chest(1, "Value: 1 GP");
		descend();
		module.onDeath(recorder);
		recorder.endRun("logout");              // what the plugin does on the login screen

		assertEquals("death", onlyRun().get("outcome").getAsString());
	}

	@Test
	public void aNewAttemptAfterADeathIsASeparateRun() throws Exception
	{
		bossAppears();
		module.onDeath(recorder);
		tick();
		bossAppears();                          // straight back in
		chest(1, "Value: 1 GP");
		claim();

		List<String> lines = written();
		assertEquals(2, lines.size());
		assertEquals("death", gson.fromJson(lines.get(0), JsonObject.class).get("outcome").getAsString());
		assertEquals("claim", gson.fromJson(lines.get(1), JsonObject.class).get("outcome").getAsString());
	}

	// ---- signals twice, late, or missing -----------------------------
	@Test
	public void aClearAnnouncedTwiceIsOneDelve() throws Exception
	{
		bossAppears();
		delveLine(1, "0:45");
		chest(1, "Value: 1 GP");
		delveLine(1, "0:45");                   // and again, late
		claim();

		JsonObject run = onlyRun();
		assertEquals(1, run.getAsJsonArray("boundaries").size());
		assertEquals(45.0, boundary(run, 0).get("duration_s").getAsDouble(), 0.001);
	}

	@Test
	public void theChatLineArrivingAfterTheChestStillSetsTheTiming() throws Exception
	{
		bossAppears();
		chest(1, "Value: 1 GP");
		delveLine(1, "0:52");
		claim();

		JsonObject run = onlyRun();
		assertEquals(1, run.getAsJsonArray("boundaries").size());
		assertEquals(52.0, boundary(run, 0).get("duration_s").getAsDouble(), 0.001);
	}

	@Test
	public void theBossReappearingBeforeTheChestIsNotANewDelve() throws Exception
	{
		bossAppears();
		delveLine(1, "0:45");
