		assertEquals(15, qty(boundary(run, 1).getAsJsonArray("loot"), COAL));
	}

	// ---- leaving -----------------------------------------------------
	@Test
	public void leavingTheInstanceWithoutClaimingEndsTheRunAsUnknown() throws Exception
	{
		bossAppears();
		pile.put(COAL, 40);
		chest(1, "Value: 6,000 GP");
		descend();

		instanced = false;                      // teleported out
		ticks(20);

		JsonObject run = onlyRun();
		assertEquals("unknown", run.get("outcome").getAsString());
		assertEquals("the delve never finished is not a delve of the record",
			1, run.getAsJsonArray("boundaries").size());
		assertEquals(6_000, run.get("chest_value_last").getAsInt());
		assertFalse("and the module has let go of the area", module.isInArea(null, null));
	}

	@Test
	public void afterAClaimTheModuleLetsGoOnceThePlayerIsOutside() throws Exception
	{
		bossAppears();
		chest(1, "Value: 1 GP");
		claim();
		instanced = false;
		ticks(20);

		assertFalse(module.isInArea(null, null));
		assertEquals(1, written().size());
	}

	@Test
	public void anArenaThatIsNotInstancedIsNotTreatedAsLeft() throws Exception
	{
		// The delves being instanced is learned from where the boss shows up, never
		// assumed. Were they not, standing outside an instance must mean nothing.
		instanced = false;
		bossAppears();
		ticks(40);

		assertTrue(recorder.runOpen());
		assertTrue(written().isEmpty());
	}

	@Test
	public void aRunWithNothingInItWritesNothing() throws Exception
	{
		bossAppears();
		recorder.endRun("logout");
		assertTrue(written().isEmpty());
	}

	// ---- parsing -----------------------------------------------------
	@Test
	public void theTitleGivesTheDelveNumber()
	{
		assertEquals(Integer.valueOf(2), DoomModule.parseLevel("Level 2 Complete!"));
		assertEquals(Integer.valueOf(14), DoomModule.parseLevel("<col=ff981f>Level 14 Complete!</col>"));
		assertNull(DoomModule.parseLevel("Complete!"));
		assertNull(DoomModule.parseLevel(null));
	}

	@Test
	public void theValueTextIsParsedHoweverItIsPunctuated()
	{
		assertEquals(Integer.valueOf(124_500), DoomModule.parseGp("Value: 124,500 GP"));
		assertEquals(Integer.valueOf(124_500), DoomModule.parseGp("124500"));
		assertEquals(Integer.valueOf(1), DoomModule.parseGp("Value: 1 GP"));
		assertEquals(Integer.valueOf(12_345_678), DoomModule.parseGp("Earned: 12 345 678 coins"));
		assertEquals("digits inside a colour tag are not the value",
			Integer.valueOf(900), DoomModule.parseGp("<col=ff9040>Value: 900 GP</col>"));
	}

	@Test
	public void unexpectedValueTextRecordsNothingRatherThanSomethingWrong()
	{
		assertNull(DoomModule.parseGp("Value: unknown"));
		assertNull(DoomModule.parseGp(""));
		assertNull(DoomModule.parseGp(null));
	}
}

package io.github.giwasawa.bosslab.bosses.doom;

import com.google.gson.Gson;
import io.github.giwasawa.bosslab.core.BossSpec;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The game ids in the Doom spec are the ones RuneLite itself uses.
 *
 * <p>The spec holds them as plain numbers, because nothing boss-specific is hard-coded
 * in Java. This is what stops those numbers being guesses: each is checked against the
 * constant RuneLite generates from the game cache, in the client this plugin is built
 * against. If Jagex renumbers something and RuneLite follows, this fails and names it.
 */
public class SpecIdsTest
{
	private BossSpec.Ids ids;

	@Before
	public void setUp() throws Exception
	{
		ids = BossSpec.load(new Gson(), "doom-of-mokhaiotl").ids;
	}

	@Test
	public void theEndOfDelveInterface()
	{
		assertEquals(InterfaceID.DOM_END_LEVEL_UI, (int) ids.widget("loot_chest_group"));
		assertEquals(InterfaceID.DomEndLevelUi.FRAME, (int) ids.widget("loot_chest_frame"));
		assertEquals(InterfaceID.DomEndLevelUi.LOOT_VALUE, (int) ids.widget("loot_chest_value"));
		assertEquals(InterfaceID.DomEndLevelUi.LOOT_CONTENTS, (int) ids.widget("loot_chest_contents"));
		assertEquals(InterfaceID.DomEndLevelUi.BTN_CLAIM, (int) ids.widget("btn_claim"));
		assertEquals(InterfaceID.DomEndLevelUi.BTN_DESCEND, (int) ids.widget("btn_descend"));
		// A component id carries its interface in the high bits.
		assertEquals((int) ids.widget("loot_chest_group"), ids.widget("loot_chest_frame") >> 16);
	}

	@Test
	public void theClaimScriptAndTheLootPile()
	{
		assertEquals(ScriptID.DOM_LOOT_CLAIM, (int) ids.script("loot_claim"));
		assertEquals(InventoryID.DOM_LOOTPILE, (int) ids.inventory("loot_pile"));
		assertEquals(InventoryID.DOM_LOOTPILE_DURING, (int) ids.inventory("loot_pile_during"));
	}

	@Test
	public void theBoss()
	{
		assertEquals(NpcID.DOM_BOSS, (int) ids.npcs.get("doom"));
		assertEquals(NpcID.DOM_BOSS_SHIELDED, (int) ids.npcs.get("doom_shielded"));
		assertEquals(NpcID.DOM_BOSS_BURROWED, (int) ids.npcs.get("doom_burrowed"));
	}

	@Test
	public void theVarpsCaptureModeWatches()
	{
		assertEquals(VarPlayerID.DOM_LAST_DELVE_LEVEL, (int) ids.varps.get("last_delve_level"));
		assertEquals(VarPlayerID.DOM_TOTAL_DURATION, (int) ids.varps.get("total_duration"));
		assertEquals(VarPlayerID.DOM_LAST_LEVEL_DURATION, (int) ids.varps.get("last_level_duration"));
		assertEquals(VarPlayerID.DOM_LEVEL_START_TIME, (int) ids.varps.get("level_start_time"));
		assertEquals(VarPlayerID.DOM_CURRENT_LEVEL_TEMP, (int) ids.varps.get("current_level_temp"));
	}
}

package io.github.giwasawa.bosslab.core;

import com.google.gson.Gson;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The bundled spec resource is generated from spec.yaml. These tests guard the parts the
 * plugin depends on, so a bad regeneration fails here rather than in game.
 */
public class BossSpecTest
{
	private BossSpec spec;

	@Before
	public void setUp() throws Exception
	{
		spec = BossSpec.load(new Gson(), "doom-of-mokhaiotl");
	}

	@Test
	public void loadsTheGeneratedResource()
	{
		assertEquals("doom-of-mokhaiotl", spec.id);
		assertEquals("Doom of Mokhaiotl", spec.name);
		assertEquals(9, spec.rateCapAt);
		assertEquals("8+", spec.scoreboardCapLabel);
		assertEquals("delve", spec.boundaryUnit);
		assertEquals(4, spec.uniques.size());
	}

	@Test
	public void everyChatPatternCompiles()
	{
		assertFalse(spec.chatPatterns.isEmpty());
		for (BossSpec.ChatPattern p : spec.chatPatterns)
		{
			assertNotNull("pattern " + p.key + " must compile as a Java regex", p.compiled());
		}
	}

	@Test
	public void parsesADelveCompletionLine()
	{
		Pattern p = spec.pattern("delve_complete").compiled();
		Matcher m = p.matcher("Delve level: 7 duration: 2:23. Personal best: 2:23");
		assertTrue(m.find());
		assertEquals("7", m.group("delve"));
		assertEquals("2:23", m.group("duration"));
		assertEquals("2:23", m.group("pb"));
	}

	@Test
	public void parsesPreciseTimingWithMilliseconds()
	{
		// RuneLite's "Enable precise timing" setting adds fractional seconds.
		Matcher m = spec.pattern("delve_complete").compiled()
			.matcher("Delve level: 8 duration: 1:49.20. Personal best: 1:45.00");
		assertTrue(m.find());
		assertEquals("1:49.20", m.group("duration"));
		assertEquals("1:45.00", m.group("pb"));
	}

	@Test
	public void parsesADelveLineWithNoPersonalBest()
	{
		Matcher m = spec.pattern("delve_complete").compiled()
			.matcher("Delve level: 4 duration: 1:24.");
		assertTrue(m.find());
		assertEquals("4", m.group("delve"));
		assertNull(m.group("pb"));
	}

	@Test
	public void parsesTheWholeRunLine()
	{
		Matcher m = spec.pattern("run_complete").compiled()
			.matcher("Delve level 1 - 8 duration: 5:54. Personal best: 5:40");
		assertTrue(m.find());
		assertEquals("5:54", m.group("duration"));
	}

	@Test
	public void theWholeRunLineDoesNotMatchASingleDelveLine()
	{
		// "Delve level 1 - 8" and "Delve level: 1" must not be confused for each other,
		// or a run split would be recorded as a delve clear.
		assertFalse(spec.pattern("run_complete").compiled()
			.matcher("Delve level: 1 duration: 0:40. Personal best: 0:35").find());
		assertFalse(spec.pattern("delve_complete").compiled()
			.matcher("Delve level 1 - 8 duration: 5:54. Personal best: 5:40").find());
	}

	@Test
	public void parsesDeepDelvesCompleted()
	{
		Matcher m = spec.pattern("deep_delves").compiled().matcher("Deep delves completed: 12");
		assertTrue(m.find());
		assertEquals("12", m.group("count"));
	}

	@Test
	public void deepDelvesCarryTheScoreboardLabel()
	{
		// The scoreboard has separate rows for 8 and 8+, so delve 8 keeps its own label
		// and everything from 9 on is bucketed as 8+.
		assertEquals("7", spec.labelFor(7));
		assertEquals("8", spec.labelFor(8));
		assertEquals("8+", spec.labelFor(9));
		assertEquals("8+", spec.labelFor(27));
	}

	@Test
	public void knowsTheUntradeablesIncludingTheOnesTheBriefWasUnsureOf()
	{
		assertTrue("spirit seed", spec.expectedUntradeable(5317));
		assertTrue("sun-kissed bones", spec.expectedUntradeable(29378));
		assertTrue("moon key", spec.expectedUntradeable(30105));
		assertTrue("the cloth itself", spec.expectedUntradeable(31109));
		// The ordinary tooth half of key is a different, tradeable item. Valuing the
		// wrong one would quietly inflate every run.
		assertFalse("ordinary tooth half of key", spec.expectedUntradeable(985));
		assertTrue("elite clue, matched by name", spec.expectedUntradeableName("Clue scroll (elite)"));
	}

	@Test
	public void carriesTheClothCraftedValueRule()
	{
		BossSpec.CraftedValue rule = spec.crafted(31109);
		assertNotNull(rule);
		assertEquals(31106, rule.outputItemId);   // confliction gauntlets
		assertEquals(2, rule.subtract.size());    // bracelet and 10,000 tears
		assertEquals(0.02, rule.geTaxRate, 1e-9);
		assertEquals(5_000_000L, rule.geTaxCap);
	}

	@Test
	public void mapsAnItemIdBackToItsUniqueKey()
	{
		assertEquals("cloth", spec.uniqueKeyForItem(31109));
		assertEquals("treads", spec.uniqueKeyForItem(31088));
		assertNull(spec.uniqueKeyForItem(995));
	}

	@Test
	public void theLootChestWidgetsAreMappedFromRuneLitesOwnConstants()
	{
		// These came from InterfaceID$DomEndLevelUi in runelite-api, which is generated
		// from the game cache, so they did not need a capture session to find.
		// A component id packs its group in the high bits: 60227604 >> 16 == 919.
		assertEquals(Integer.valueOf(919), spec.ids.widget("loot_chest_group"));
		assertEquals(Integer.valueOf(60227604), spec.ids.widget("loot_chest_value"));
		assertEquals(Integer.valueOf(60227603), spec.ids.widget("loot_chest_contents"));
		assertEquals("the group must match the components it contains",
			919, spec.ids.widget("loot_chest_value") >> 16);
	}

	@Test
	public void whatIsStillUnknownIsNullRatherThanGuessed()
	{
		// Capture mode fills these in. A null means "not known yet", so the plugin falls
		// back to chat parsing instead of acting on a wrong id.
		assertNull("no delve varbit found in gameval", spec.ids.varbit("delve_level"));
		assertTrue("regions stay empty: the delves are instanced",
			spec.ids.regions.isEmpty());
	}
}

package io.github.giwasawa.bosslab.core;

import com.google.gson.Gson;
import io.github.giwasawa.bosslab.core.model.LoggedItem;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Snapshots, diffs, dose counting and the rune pouch.
 *
 * <p>These are the places a supply cost can quietly go wrong, so they are pinned here
 * rather than discovered on the Windows PC.
 */
public class InventoryTrackerTest
{
	private static final int BREW4 = 6685;
	private static final int BREW3 = 6687;
	private static final int RESTORE4 = 3024;
	private static final int SHARK = 385;
	private static final int COAL = 453;
	private static final int COAL_NOTED = 454;
	private static final int DEATH_RUNE = 560;
	private static final int BLOOD_RUNE = 565;

	private Client client;
	private ItemManager itemManager;
	private InventoryTracker tracker;
	private BossSpec spec;

	private final Map<Integer, String> names = new HashMap<>();

	@Before
	public void setUp() throws Exception
	{
		client = Mockito.mock(Client.class);
		itemManager = Mockito.mock(ItemManager.class);
		tracker = new InventoryTracker(client, new Pricer(itemManager));
		spec = BossSpec.load(new Gson(), "doom-of-mokhaiotl");

		names.put(BREW4, "Saradomin brew(4)");
		names.put(BREW3, "Saradomin brew(3)");
		names.put(RESTORE4, "Super restore(4)");
		names.put(SHARK, "Shark");
		names.put(COAL, "Coal");
		names.put(COAL_NOTED, "Coal");
		names.put(DEATH_RUNE, "Death rune");
		names.put(BLOOD_RUNE, "Blood rune");

		for (Map.Entry<Integer, String> e : names.entrySet())
		{
			ItemComposition comp = Mockito.mock(ItemComposition.class);
			Mockito.when(comp.getName()).thenReturn(e.getValue());
			Mockito.when(comp.isTradeable()).thenReturn(true);
			// Only the noted coal reports a note, linking back to the loose id.
			Mockito.when(comp.getNote()).thenReturn(e.getKey() == COAL_NOTED ? 799 : -1);
			Mockito.when(comp.getLinkedNoteId()).thenReturn(e.getKey() == COAL_NOTED ? COAL : -1);
			Mockito.when(itemManager.getItemComposition(e.getKey())).thenReturn(comp);
		}
		Mockito.when(itemManager.getItemPrice(BREW4)).thenReturn(12_000L);
		Mockito.when(itemManager.getItemPrice(BREW3)).thenReturn(9_000L);
		Mockito.when(itemManager.getItemPrice(RESTORE4)).thenReturn(10_000L);
		Mockito.when(itemManager.getItemPrice(SHARK)).thenReturn(1_100L);
		Mockito.when(itemManager.getItemPrice(COAL)).thenReturn(147L);
		Mockito.when(itemManager.getItemPrice(DEATH_RUNE)).thenReturn(180L);
		Mockito.when(itemManager.getItemPrice(BLOOD_RUNE)).thenReturn(320L);
	}

	private void setInventory(int[]... idQtyPairs)
	{
		Item[] items = new Item[idQtyPairs.length];
		for (int i = 0; i < idQtyPairs.length; i++)
		{
			items[i] = new Item(idQtyPairs[i][0], idQtyPairs[i][1]);
		}
		ItemContainer c = Mockito.mock(ItemContainer.class);
		Mockito.when(c.getItems()).thenReturn(items);
		Mockito.when(client.getItemContainer(InventoryID.INV)).thenReturn(c);
	}

	private LoggedItem find(List<LoggedItem> items, int itemId)
	{
		for (LoggedItem i : items)
		{
			if (i.itemId == itemId)
			{
				return i;
			}
		}
		return null;
	}

	@Test
	public void aFourDoseBecomingAThreeDoseIsOneDose()
	{
		// The whole point of dose counting: this must read as one dose used, not as one
		// item lost and one item gained.
		setInventory(new int[]{BREW4, 1});
		InventoryTracker.Snapshot before = tracker.inventory();

		setInventory(new int[]{BREW3, 1});
		InventoryTracker.Snapshot after = tracker.inventory();

		List<LoggedItem> diff = tracker.diff(spec, before, after);
		assertEquals("one row, not two", 1, diff.size());
		assertEquals(-1, diff.get(0).qty);
	}

	@Test
	public void doseRowsArePricedPerDose()
	{
		setInventory(new int[]{BREW4, 1});
		List<LoggedItem> rows = tracker.toLogged(spec, tracker.inventory());

		LoggedItem brew = rows.get(0);
		assertEquals("four doses in the row", 4, brew.qty);
		// A full brew is 12,000, so a dose is 3,000. Four doses still total 12,000.
		assertEquals(Integer.valueOf(3_000), brew.priceEach);
		assertEquals(12_000, brew.qty * brew.priceEach);
	}

	@Test
	public void potionsOfDifferentDosesAddUpAsOneFamily()
	{
		setInventory(new int[]{BREW4, 2}, new int[]{BREW3, 1});
		List<LoggedItem> rows = tracker.toLogged(spec, tracker.inventory());

		assertEquals("brews are one row whatever the mix", 1, rows.size());
		assertEquals("2x4 + 1x3 doses", 11, rows.get(0).qty);
	}

	@Test
	public void differentPotionsStaySeparate()
	{
		setInventory(new int[]{BREW4, 1}, new int[]{RESTORE4, 1});
		assertEquals(2, tracker.toLogged(spec, tracker.inventory()).size());
	}

	@Test
	public void notedAndLooseStacksAreTheSameGoods()
	{
		setInventory(new int[]{COAL, 10}, new int[]{COAL_NOTED, 20});
		List<LoggedItem> rows = tracker.toLogged(spec, tracker.inventory());

		assertEquals("one coal row", 1, rows.size());
		assertEquals(30, rows.get(0).qty);
		assertEquals("priced as the loose item", Integer.valueOf(147), rows.get(0).priceEach);
	}

	@Test
	public void consumingFoodShowsAsANegativeQuantity()
	{
		setInventory(new int[]{SHARK, 12});
		InventoryTracker.Snapshot before = tracker.inventory();
		setInventory(new int[]{SHARK, 9});
		List<LoggedItem> diff = tracker.diff(spec, before, tracker.inventory());

		assertEquals(-3, find(diff, SHARK).qty);
	}

	@Test
	public void lootArrivingShowsAsAPositiveQuantity()
	{
		setInventory(new int[]{SHARK, 12});
		InventoryTracker.Snapshot before = tracker.inventory();
		setInventory(new int[]{SHARK, 12}, new int[]{COAL, 30});
		List<LoggedItem> diff = tracker.diff(spec, before, tracker.inventory());

		assertEquals(1, diff.size());
		assertEquals(30, find(diff, COAL).qty);
	}

	@Test
	public void anUnchangedInventoryProducesNoRows()
	{
		setInventory(new int[]{SHARK, 12}, new int[]{BREW4, 2});
		InventoryTracker.Snapshot before = tracker.inventory();
		InventoryTracker.Snapshot after = tracker.inventory();

		assertTrue("nothing changed, so nothing is logged",
			tracker.diff(spec, before, after).isEmpty());
	}

	@Test
	public void theRunePouchIsReadFromItsVarbits()
	{
		EnumComposition runes = Mockito.mock(EnumComposition.class);
		// The type varbit is an index into a game enum, not an item id.
		Mockito.when(runes.getIntValue(1)).thenReturn(DEATH_RUNE);
		Mockito.when(runes.getIntValue(2)).thenReturn(BLOOD_RUNE);
		Mockito.when(client.getEnum(Mockito.anyInt())).thenReturn(runes);

		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(1);
		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(400);
		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2)).thenReturn(2);
		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2)).thenReturn(250);

		List<LoggedItem> rows = tracker.toLogged(spec, tracker.runePouch());

		assertEquals(2, rows.size());
		assertEquals(400, find(rows, DEATH_RUNE).qty);
		assertEquals(250, find(rows, BLOOD_RUNE).qty);
	}

	@Test
	public void theDivinePouchExtraSlotsAreRead()
	{
		// Slots 4 to 6 exist for the divine pouch. Missing them would undercount runes.
		EnumComposition runes = Mockito.mock(EnumComposition.class);
		Mockito.when(runes.getIntValue(3)).thenReturn(DEATH_RUNE);
		Mockito.when(client.getEnum(Mockito.anyInt())).thenReturn(runes);
		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_4)).thenReturn(3);
		Mockito.when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_4)).thenReturn(123);

		List<LoggedItem> rows = tracker.toLogged(spec, tracker.runePouch());

		assertEquals(1, rows.size());
		assertEquals(123, rows.get(0).qty);
	}

	@Test
	public void anEmptyOrMissingContainerIsHandled()
	{
		Mockito.when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
		assertTrue(tracker.toLogged(spec, tracker.inventory()).isEmpty());
	}
}

package io.github.giwasawa.bosslab.core;

import io.github.giwasawa.bosslab.TestFiles;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.ZoneOffset;
import java.time.YearMonth;
import java.util.List;
import java.util.zip.GZIPOutputStream;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * File handling: appending, rotation, and the keep-raw-months prune.
 *
 * <p>The prune is destructive, so its arithmetic is pinned here. Totals must be baked in
 * before the diffs they came from are dropped, or the gp figures would be lost.
 */
public class JsonlWriterTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Gson gson;
	private JsonlWriter writer;
	private File base;

	@Before
	public void setUp()
	{
		gson = new Gson();
		base = folder.getRoot();
		writer = new JsonlWriter(TestFiles.rooted(base), "doom-of-mokhaiotl", gson);
	}

	/** A run with two delves: loot of 10,000, supplies of 3,000. */
	private String claimRun(String id)
	{
		return "{\"run_id\":\"" + id + "\",\"boss\":\"doom-of-mokhaiotl\","
			+ "\"started_at\":\"2020-01-05T10:00:00Z\",\"outcome\":\"claim\","
			+ "\"depth_reached\":2,\"boundaries\":["
			+ "{\"index\":1,\"result\":\"cleared\",\"duration_s\":40,"
			+ "  \"loot\":[{\"id\":453,\"q\":40,\"p\":150}],"
			+ "  \"inventory_diff\":[{\"id\":385,\"q\":-1,\"p\":1000}]},"
			+ "{\"index\":2,\"result\":\"cleared\",\"duration_s\":50,"
			+ "  \"loot\":[{\"id\":560,\"q\":20,\"p\":200}],"
			+ "  \"inventory_diff\":[{\"id\":385,\"q\":-2,\"p\":1000},"
			+ "                      {\"id\":453,\"q\":40,\"p\":150}]}],"
			+ "\"inventory_start\":[{\"id\":385,\"q\":12,\"p\":1000}],"
			+ "\"unknown_events\":[{\"kind\":\"chat\",\"tick\":1,\"detail\":\"x\"}]}";
	}

	/** A death: kept nothing, forfeited 250,000, paid a 100,000 fee, used 4,000 of supplies. */
	private String deathRun(String id)
	{
		return "{\"run_id\":\"" + id + "\",\"boss\":\"doom-of-mokhaiotl\","
			+ "\"started_at\":\"2020-01-06T10:00:00Z\",\"outcome\":\"death\","
			+ "\"depth_reached\":2,\"death_fee\":100000,\"chest_value_last\":250000,"
			+ "\"boundaries\":["
			+ "{\"index\":1,\"result\":\"cleared\",\"duration_s\":40,"
			+ "  \"loot\":[{\"id\":453,\"q\":40,\"p\":150}],"
			+ "  \"inventory_diff\":[{\"id\":385,\"q\":-4,\"p\":1000}]},"
			+ "{\"index\":2,\"result\":\"died\",\"duration_s\":30}]}";
	}

	private File writeOldMonth(String name, boolean gzip, String... lines) throws IOException
	{
		base.mkdirs();
		File dir = new File(base, "doom-of-mokhaiotl");
		dir.mkdirs();
		File f = new File(dir, name);
		try (Writer w = new OutputStreamWriter(
			gzip ? new GZIPOutputStream(new FileOutputStream(f)) : new FileOutputStream(f),
			StandardCharsets.UTF_8))
		{
			for (String line : lines)
			{
				w.write(line);
				w.write("\n");
			}
		}
		return f;
	}

	private JsonObject firstRecord(File f) throws IOException
	{
		List<String> lines = Files.readAllLines(f.toPath(), StandardCharsets.UTF_8);
		return gson.fromJson(lines.get(0), JsonObject.class);
	}

	@Test
	public void appendsOnePerLineIntoTheCurrentMonth() throws IOException
	{
		writer.append(new int[]{1, 2});
		writer.append(new int[]{3});
		File f = TestFiles.file(writer.currentFile());
		assertTrue(f.exists());
		assertTrue(f.getName().startsWith("runs-"));
		assertEquals(2, TestFiles.lines(writer.currentFile()).size());
	}

	@Test
	public void theFileNameSaysNothingAboutTheAccount()
	{
		// Section 2.3: file names are generic and never contain the character name.
		writer.append(new int[]{1});
		String name = TestFiles.file(writer.currentFile()).getName();
		assertTrue(name.matches("runs-\\d{4}-\\d{2}\\.jsonl"));
	}

	@Test
	public void rotationCompressesAPreviousMonthAndLeavesTheCurrentOneAlone() throws Exception
	{
		writeOldMonth("runs-2020-01.jsonl", false, claimRun("old"));
		writer.append(new int[]{1});
		File current = TestFiles.file(writer.currentFile());

		writer.rotate();

		File dir = new File(base, "doom-of-mokhaiotl");
		assertFalse("the old month is no longer plain",
			new File(dir, "runs-2020-01.jsonl").exists());
		assertTrue("it is now compressed", new File(dir, "runs-2020-01.jsonl.gz").exists());
		assertTrue("the current month is untouched", current.exists());
	}

	@Test
	public void pruningIsOffByDefault() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, claimRun("a"));
		writer.prune(0);
		assertFalse("0 months means keep everything forever",
			firstRecord(f).has("pruned"));
	}

	@Test
	public void pruningLeavesRecentMonthsAlone() throws Exception
	{
		String recent = "runs-" + YearMonth.now(ZoneOffset.UTC).minusMonths(1) + ".jsonl";
		File f = writeOldMonth(recent, false, claimRun("a"));
		writer.prune(6);
		assertFalse(firstRecord(f).has("pruned"));
	}

	@Test
	public void pruningBakesTheTotalsInBeforeDroppingTheDetail() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, claimRun("a"));

		writer.prune(1);

		JsonObject run = firstRecord(f);
		assertTrue(run.get("pruned").getAsBoolean());
		JsonObject totals = run.getAsJsonObject("totals");
		// loot 40x150 + 20x200 = 10,000. Supplies: 3 sharks at 1,000 = 3,000.
		// The 40 coal arriving in the diff is loot, not a supply, so it does not count.
		assertEquals(10_000, totals.get("loot").getAsLong());
		assertEquals(3_000, totals.get("supplies").getAsLong());
		assertEquals(0, totals.get("loot_lost").getAsLong());
		assertEquals(7_000, totals.get("net").getAsLong());
	}

	@Test
	public void pruningRemovesTheRawDetailButKeepsTheSummary() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, claimRun("a"));

		writer.prune(1);

		JsonObject run = firstRecord(f);
		assertFalse(run.has("inventory_start"));
		assertFalse(run.has("unknown_events"));
		JsonObject first = run.getAsJsonArray("boundaries").get(0).getAsJsonObject();
		assertFalse(first.has("loot"));
		assertFalse(first.has("inventory_diff"));
		// The summary of the run survives, so timings and outcomes still work.
		assertEquals("claim", run.get("outcome").getAsString());
		assertEquals(2, run.get("depth_reached").getAsInt());
		assertEquals(2, run.getAsJsonArray("boundaries").size());
		assertEquals(40, first.get("duration_s").getAsInt());
		assertEquals("cleared", first.get("result").getAsString());
	}

	@Test
	public void aPrunedDeathKeepsNothingAndStillPaysTheFee() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, deathRun("d"));

		writer.prune(1);

		JsonObject totals = firstRecord(f).getAsJsonObject("totals");
		assertEquals("a death keeps nothing", 0, totals.get("loot").getAsLong());
		assertEquals("the chest value is what was forfeited",
			250_000, totals.get("loot_lost").getAsLong());
		assertEquals(4_000, totals.get("supplies").getAsLong());
		assertEquals("minus supplies, minus the fee",
			-104_000, totals.get("net").getAsLong());
	}

	@Test
	public void pruningIsIdempotent() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, claimRun("a"));
		writer.prune(1);
		long net = firstRecord(f).getAsJsonObject("totals").get("net").getAsLong();

		writer.prune(1);

		// A second pass must not recompute totals from diffs that are no longer there,
		// which would zero them out.
		assertEquals(net, firstRecord(f).getAsJsonObject("totals").get("net").getAsLong());
		assertEquals(7_000, net);
	}

	@Test
	public void anAlreadyCompressedMonthIsPrunedInPlace() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl.gz", true, claimRun("a"), claimRun("b"));

		writer.prune(1);

		assertTrue("still compressed", f.exists() && f.getName().endsWith(".gz"));
		// Read it back through the engine-facing path: gzip in, two pruned records out.
		try (java.io.BufferedReader r = new java.io.BufferedReader(new java.io.InputStreamReader(
			new java.util.zip.GZIPInputStream(new java.io.FileInputStream(f)),
			StandardCharsets.UTF_8)))
		{
			int n = 0;
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.trim().isEmpty())
				{
					continue;
				}
				assertTrue(gson.fromJson(line, JsonObject.class).get("pruned").getAsBoolean());
				n++;
			}
			assertEquals(2, n);
		}
	}

	@Test
	public void anUnparseableLineIsKeptRatherThanDiscarded() throws Exception
	{
		File f = writeOldMonth("runs-2020-01.jsonl", false, "{not json", claimRun("a"));

		writer.prune(1);

		List<String> lines = Files.readAllLines(f.toPath(), StandardCharsets.UTF_8);
		assertEquals(2, lines.size());
		assertEquals("a damaged line is a player's data too, so it stays",
			"{not json", lines.get(0));
	}

	@Test
	public void anUnpricedItemContributesNothingRatherThanAGuess() throws Exception
	{
		String run = "{\"run_id\":\"u\",\"outcome\":\"claim\",\"depth_reached\":1,"
			+ "\"boundaries\":[{\"index\":1,\"result\":\"cleared\","
			+ "\"loot\":[{\"id\":999,\"q\":5,\"p\":null,\"src\":\"missing\"},"
			+ "          {\"id\":453,\"q\":10,\"p\":150}],"
			+ "\"inventory_diff\":[]}]}";
		File f = writeOldMonth("runs-2020-01.jsonl", false, run);

		writer.prune(1);

		assertEquals(1_500,
			firstRecord(f).getAsJsonObject("totals").get("loot").getAsLong());
	}

	@Test
	public void runsTodayCountsTheWrittenFieldNameAndTheGivenWindow() throws IOException
	{
		// The panel's count used to look for "startedAt", which is the Java field name,
		// in a file that holds "started_at". It could only ever say zero.
		String month = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM")
			.format(java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC));
		writeOldMonth("runs-" + month + ".jsonl", false,
			"{\"run_id\":\"a\",\"started_at\":\"" + month + "-10T02:59:59Z\"}",
			"{\"run_id\":\"b\",\"started_at\":\"" + month + "-10T03:00:00Z\"}",
			"{\"run_id\":\"c\",\"started_at\":\"" + month + "-10T23:30:00Z\"}",
			"{\"run_id\":\"d\",\"started_at\":\"" + month + "-11T03:00:00Z\"}");

		// A player's day at UTC-3: from 03:00Z to 03:00Z the next day.
		java.time.Instant from = java.time.Instant.parse(month + "-10T03:00:00Z");
		assertEquals(2, writer.countBetween(from, from.plusSeconds(86_400)));
	}
}

package io.github.giwasawa.bosslab.core;

import com.google.gson.Gson;
import io.github.giwasawa.bosslab.core.model.LoggedItem;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The order of checks from section 4.1, which decides every gp figure in the project.
 */
public class PricerTest
{
	// Confliction gauntlets, tormented bracelet, demon tear, Mokhaiotl cloth.
	private static final int GAUNTLETS = 31106;
	private static final int BRACELET = 19544;
	private static final int TEAR = 31111;
	private static final int CLOTH = 31109;
	private static final int COAL = 453;
	private static final int BONES = 29378;       // sun-kissed bones, untradeable
	private static final int ORDINARY_KEY = 985;  // tradeable tooth half of key

	private ItemManager itemManager;
	private Pricer pricer;
	private BossSpec spec;

	@Before
	public void setUp() throws Exception
	{
		itemManager = Mockito.mock(ItemManager.class);
		pricer = new Pricer(itemManager);
		spec = BossSpec.load(new Gson(), "doom-of-mokhaiotl");
	}

	private void price(int itemId, long value)
	{
		Mockito.when(itemManager.getItemPrice(itemId)).thenReturn(value);
	}

	private void tradeable(int itemId, boolean canTrade, String name)
	{
		ItemComposition comp = Mockito.mock(ItemComposition.class);
		Mockito.when(comp.isTradeable()).thenReturn(canTrade);
		Mockito.when(comp.getName()).thenReturn(name);
		Mockito.when(comp.getNote()).thenReturn(-1);
		Mockito.when(itemManager.getItemComposition(itemId)).thenReturn(comp);
	}

	@Test
	public void aCraftedRuleBeatsEverythingElse()
	{
		// The cloth is untradeable, so ItemManager returns 0 for it. It must not be
		// valued at 0: its worth is the gauntlets it becomes, less the parts and tax.
		price(GAUNTLETS, 56_380_000);
		price(BRACELET, 15_000_000);
		price(TEAR, 281);
		price(CLOTH, 0);
		tradeable(CLOTH, false, "Mokhaiotl cloth");

		LoggedItem item = pricer.price(spec, CLOTH, 1, false);

		assertEquals(LoggedItem.PriceSource.CRAFTED, item.priceSource);
		// 56,380,000 - 15,000,000 - 2,810,000 - 1,127,600 tax = 37,442,400
		assertEquals(Integer.valueOf(37_442_400), item.priceEach);
	}

	@Test
	public void theGeTaxIsCapped()
	{
		// 2% of 400M would be 8M, but the cap is 5M.
		price(GAUNTLETS, 400_000_000);
		price(BRACELET, 0);
		price(TEAR, 0);
		BossSpec.CraftedValue rule = spec.crafted(CLOTH);
		// With no price for the parts the rule declines rather than guessing.
		assertNull(pricer.craftedValue(rule));

		price(BRACELET, 1);
		price(TEAR, 1);
		Integer v = pricer.craftedValue(rule);
		// 400,000,000 - 1 - 10,000 - 5,000,000 cap = 394,989,999
		assertEquals(Integer.valueOf(394_989_999), v);
	}

	@Test
	public void anUntradeableItemIsWorthNothing()
	{
		tradeable(BONES, false, "Sun-kissed bones");
		price(BONES, 160);   // a shop value, not a market price

		LoggedItem item = pricer.price(spec, BONES, 40, false);

		assertEquals(LoggedItem.PriceSource.UNTRADEABLE_ZERO, item.priceSource);
		assertEquals(Integer.valueOf(0), item.priceEach);
	}

	@Test
	public void anItemMatchedByNameIsAlsoWorthNothing()
	{
		// An elite clue's id varies per instance, so the spec matches it by name.
		int someClueId = 12073;
		tradeable(someClueId, true, "Clue scroll (elite)");
		price(someClueId, 0);

		LoggedItem item = pricer.price(spec, someClueId, 1, false);

		assertEquals(LoggedItem.PriceSource.UNTRADEABLE_ZERO, item.priceSource);
	}

	@Test
	public void aTradeableItemUsesTheCurrentPrice()
	{
		tradeable(COAL, true, "Coal");
		price(COAL, 147);

		LoggedItem item = pricer.price(spec, COAL, 30, true);

		assertEquals(LoggedItem.PriceSource.ITEM_MANAGER, item.priceSource);
		assertEquals(Integer.valueOf(147), item.priceEach);
		assertEquals(Boolean.TRUE, item.noted);
		assertEquals(30, item.qty);
	}

	@Test
	public void aTradeableItemWithNoPriceIsFlaggedRatherThanGuessed()
	{
		// The brief is explicit: record null, do not guess, and let the dashboard say
		// "price missing". Null is not zero.
		tradeable(COAL, true, "Coal");
		price(COAL, 0);

		LoggedItem item = pricer.price(spec, COAL, 5, false);

		assertEquals(LoggedItem.PriceSource.MISSING, item.priceSource);
		assertNull(item.priceEach);
	}

	@Test
	public void theOrdinaryToothHalfOfKeyIsStillWorthSomething()
	{
		// Only the moon key variant (30105) is untradeable. Treating 985 as untradeable
		// would quietly lose value on every run that drops one.
		tradeable(ORDINARY_KEY, true, "Tooth half of key");
		price(ORDINARY_KEY, 24_000);

		LoggedItem item = pricer.price(spec, ORDINARY_KEY, 1, false);

		assertEquals(LoggedItem.PriceSource.ITEM_MANAGER, item.priceSource);
		assertEquals(Integer.valueOf(24_000), item.priceEach);
	}
}

package io.github.giwasawa.bosslab.core;

import io.github.giwasawa.bosslab.TestFiles;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import io.github.giwasawa.bosslab.core.model.BoundaryRecord;
import io.github.giwasawa.bosslab.core.model.LoggedItem;
import io.github.giwasawa.bosslab.core.model.RunRecord;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's file format has to match {@code data/schema/run-log.schema.json}, because
 * that schema is also what the Python engine reads.
 *
 * <p>This exists because of a real bug. Gson names fields after the Java field by
 * default, so the plugin was writing {@code runId}, {@code startedAt} and
 * {@code unknownEvents} while the schema and the engine expected {@code run_id},
 * {@code started_at} and {@code unknown_events}. Nothing downstream could have read a
 * single line. Neither test suite caught it: the Java tests read Java names and the
 * Python tests used hand-written snake_case fixtures, so each side agreed with itself.
 *
 * <p>The guard is to compare what the writer actually emits against the schema's own
 * property names, so the two cannot drift apart again.
 */
public class WireFormatTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	private Gson gson;
	private JsonlWriter writer;
	private JsonObject schema;

	@Before
	public void setUp() throws IOException
	{
		gson = new Gson();
		writer = new JsonlWriter(TestFiles.rooted(folder.getRoot()), "doom-of-mokhaiotl", gson);
		schema = readSchema("run-log.schema.json");
	}

	/**
	 * Tests run with the Gradle project directory as the working directory. In the
	 * development repository that is plugin/, with the schemas one level up; in the
	 * published plugin repository the project is the root and they sit beside it.
	 */
	private JsonObject readSchema(String name) throws IOException
	{
		File f = new File("data/schema/" + name);
		if (!f.exists())
		{
			f = new File("../data/schema/" + name);
		}
		assertTrue("cannot find " + f.getAbsolutePath(), f.exists());
		try (FileReader r = new FileReader(f))
		{
			return gson.fromJson(r, JsonObject.class);
		}
	}

	private Set<String> propertyNames(JsonObject node)
	{
		Set<String> out = new TreeSet<>();
		JsonObject props = node.getAsJsonObject("properties");
		if (props != null)
		{
			out.addAll(props.keySet());
		}
		return out;
	}

	/** A record with every field populated, so nothing is skipped as null. */
	private RunRecord fullRecord()
	{
		RunRecord run = new RunRecord();
		run.pluginVersion = "test";
		run.boss = "doom-of-mokhaiotl";
		run.specVersion = "2026-11-26";
		run.referenceVersion = "2026-11-26";
		run.runId = "abc123";
		run.startedAt = "2026-11-26T20:00:00Z";
		run.endedAt = "2026-11-26T20:15:00Z";
		run.startTick = 100;
		run.endTick = 900;
		run.outcome = "death";
		run.depthReached = 9;
		run.deathFee = 100000;
		run.chestValueLast = 250000;

		LoggedItem item = new LoggedItem(385, -3, 1100,
			LoggedItem.PriceSource.ITEM_MANAGER, null);
		LoggedItem crafted = new LoggedItem(31109, 1, 37442400,
			LoggedItem.PriceSource.CRAFTED, Boolean.TRUE);

		BoundaryRecord b = new BoundaryRecord(9);
		b.label = "8+";
		b.result = "died";
		b.startTick = 100;
		b.endTick = 400;
		b.startedAt = "2026-11-26T20:00:00Z";
		b.endedAt = "2026-11-26T20:05:00Z";
		b.durationS = 300.0;
		b.idleS = 18.0;
		b.chestValueGp = 250000;
		b.damageTaken = 95;
		b.prayerUsed = 40;
		b.loot.add(item);
		b.loot.add(crafted);
		b.inventoryDiff.add(item);
		b.equipmentDiff.add(item);
		b.runePouchDiff.add(item);
		b.uniques.add("cloth");
		run.boundaries.add(b);

		run.inventoryStart.add(item);
		run.equipmentStart.add(item);
		run.runePouchStart.add(item);

		RunRecord.PbLine pb = new RunRecord.PbLine();
		pb.delve = 9;
		pb.durationS = 300.0;
		pb.pbS = 290.0;
		pb.isNewPb = Boolean.FALSE;
		run.pbLines.add(pb);

		run.deepDelvesCompleted = 4;
		run.unknownEvents.add(new RunRecord.UnknownEvent("chat", 123, null, "some text"));

		RunRecord.Totals totals = new RunRecord.Totals();
		totals.loot = 0;
		totals.lootLost = 250000;
		totals.supplies = 3300;
		totals.net = -103300;
		run.totals = totals;
		run.pruned = Boolean.TRUE;
		return run;
	}

	private JsonObject writeAndRead(RunRecord run) throws IOException
	{
		writer.append(run);
		List<String> lines = Files.readAllLines(TestFiles.file(writer.currentFile()).toPath(),
			StandardCharsets.UTF_8);
		assertEquals(1, lines.size());
		return gson.fromJson(lines.get(0), JsonObject.class);
	}

	/**
	 * Also dump a record where the Python validator can reach it.
	 *
	 * <p>The assertions in this class compare the writer against the schema from the
	 * Java side. CI then runs {@code tools/validate.py --logs plugin/build/wire-sample}
	 * over this file, so the format is checked by the very code that will read it in
	 * anger. That is the only check that can catch the two sides agreeing with
	 * themselves but not with each other.
	 */
	@Test
	public void dumpARecordForThePythonValidator() throws Exception
	{
		File dir = new File("build/wire-sample");
		assertTrue(dir.exists() || dir.mkdirs());
		JsonlWriter out = new JsonlWriter(TestFiles.rooted(dir), "doom-of-mokhaiotl", gson);
		File target = TestFiles.file(out.currentFile());
		if (target.exists())
		{
			assertTrue(target.delete());
		}
		// Both shapes the engine has to handle: a full record and a pruned one.
		RunRecord full = fullRecord();
		full.totals = null;
		full.pruned = null;
		full.outcome = "claim";
		full.deathFee = null;
		full.chestValueLast = null;
		out.append(full);
		out.append(fullRecord());
		assertEquals(2, TestFiles.lines(out.currentFile()).size());
	}

	@Test
	public void everyFieldTheWriterEmitsIsInTheSchema() throws Exception
	{
		JsonObject written = writeAndRead(fullRecord());
		Set<String> allowed = propertyNames(schema);

		Set<String> unexpected = new TreeSet<>(written.keySet());
		unexpected.removeAll(allowed);
		assertEquals("the writer emits field(s) the schema does not define, so the "
			+ "engine would reject the record", new TreeSet<String>(), unexpected);
	}

	@Test
	public void theWriterEmitsEveryFieldTheSchemaRequires() throws Exception
	{
		JsonObject written = writeAndRead(fullRecord());
		JsonArray required = schema.getAsJsonArray("required");
		List<String> missing = new ArrayList<>();
		for (JsonElement el : required)
		{
			if (!written.has(el.getAsString()))
			{
				missing.add(el.getAsString());
			}
		}
		assertEquals("required schema field(s) are not being written",
			new ArrayList<String>(), missing);
	}

	@Test
	public void boundaryFieldsMatchTheSchema() throws Exception
	{
		JsonObject written = writeAndRead(fullRecord());
		JsonObject boundaryDef = schema.getAsJsonObject("$defs").getAsJsonObject("boundary");
		Set<String> allowed = propertyNames(boundaryDef);

		JsonObject b = written.getAsJsonArray("boundaries").get(0).getAsJsonObject();
		Set<String> unexpected = new TreeSet<>(b.keySet());
		unexpected.removeAll(allowed);
		assertEquals("a boundary emits field(s) the schema does not define",
			new TreeSet<String>(), unexpected);
	}

	@Test
	public void itemStackFieldsMatchTheSharedDefinition() throws Exception
	{
		JsonObject written = writeAndRead(fullRecord());
		Set<String> allowed = propertyNames(
			readSchema("item-stack.defs.json").getAsJsonObject("$defs")
				.getAsJsonObject("itemStack"));

		Set<String> seen = new HashSet<>();
		JsonObject b = written.getAsJsonArray("boundaries").get(0).getAsJsonObject();
		for (String field : new String[]{"loot", "inventory_diff", "equipment_diff",
			"rune_pouch_diff"})
		{
			for (JsonElement el : b.getAsJsonArray(field))
			{
				seen.addAll(el.getAsJsonObject().keySet());
			}
		}
		assertFalse("no stacks were inspected", seen.isEmpty());

		Set<String> unexpected = new TreeSet<>(seen);
		unexpected.removeAll(allowed);
		assertEquals("an item stack emits field(s) the shared definition does not allow",
			new TreeSet<String>(), unexpected);
	}

	@Test
	public void theKeysAreSnakeCaseNotJavaFieldNames() throws Exception
	{
		JsonObject written = writeAndRead(fullRecord());
		// Spelled out, because this is the exact bug being guarded against.
		assertTrue(written.has("run_id"));
		assertTrue(written.has("started_at"));
		assertTrue(written.has("depth_reached"));
		assertTrue(written.has("unknown_events"));
		assertTrue(written.has("schema_version"));
		assertFalse(written.has("runId"));
		assertFalse(written.has("startedAt"));
		assertFalse(written.has("depthReached"));
		assertFalse(written.has("unknownEvents"));
		assertFalse(written.has("schemaVersion"));

		JsonObject b = written.getAsJsonArray("boundaries").get(0).getAsJsonObject();
		assertTrue(b.has("duration_s"));
		assertTrue(b.has("idle_s"));
		assertTrue(b.has("inventory_diff"));
		assertFalse(b.has("durationS"));
		assertFalse(b.has("inventoryDiff"));

		JsonObject totals = written.getAsJsonObject("totals");
		assertTrue(totals.has("loot_lost"));
		assertFalse(totals.has("lootLost"));
	}

	@Test
	public void itemStacksKeepTheirShortExplicitNames() throws Exception
	{
		// An explicit @SerializedName beats the naming policy, so the compact keys that
		// keep a run inside its storage budget are not expanded back out.
		JsonObject written = writeAndRead(fullRecord());
		JsonObject stack = written.getAsJsonArray("boundaries").get(0).getAsJsonObject()
			.getAsJsonArray("inventory_diff").get(0).getAsJsonObject();
		assertTrue(stack.has("id"));
		assertTrue(stack.has("q"));
		assertTrue(stack.has("p"));
		assertFalse("item_id would be the naming policy leaking through",
			stack.has("item_id"));
		assertFalse(stack.has("price_each"));
	}

