	@Test
	public void noFieldLooksLikePersonalData() throws Exception
	{
		// Section 2.3 is non-negotiable. The same check the Python validator runs, so a
		// leak fails here too rather than only after a real session.
		Set<String> banned = new HashSet<>(java.util.Arrays.asList(
			"rsn", "username", "user", "playername", "player", "account", "accounthash",
			"hash", "email", "ip", "ipaddress", "displayname", "display", "login",
			"character", "charactername"));
		List<String> hits = new ArrayList<>();
		collectKeys(writeAndRead(fullRecord()), "", banned, hits);
		assertEquals("a field name looks like personal data", new ArrayList<String>(), hits);
	}

	private void collectKeys(JsonElement node, String trail, Set<String> banned,
							 List<String> hits)
	{
		if (node.isJsonObject())
		{
			for (String key : node.getAsJsonObject().keySet())
			{
				for (String word : key.toLowerCase().split("[^a-z0-9]+"))
				{
					if (banned.contains(word))
					{
						hits.add(trail + "/" + key);
					}
				}
				collectKeys(node.getAsJsonObject().get(key), trail + "/" + key, banned, hits);
			}
		}
		else if (node.isJsonArray())
		{
			for (JsonElement el : node.getAsJsonArray())
			{
				collectKeys(el, trail, banned, hits);
			}
		}
	}
